.lm_goldenlayout {
  background-color: var(--base) !important;
  color: var(--foreground) !important;
  z-index: var(--z-base) !important;
  position: relative !important;
  pointer-events: auto !important;
  overflow: hidden !important;
}

.lm_goldenlayout * {
  pointer-events: auto !important;
}

.lm_root {
  z-index: var(--z-base) !important;
  position: relative !important;
  overflow: hidden !important;
}

.lm_item {
