// [👤compose🖱️sketchpad⚙️tailwindconfig🔖configuration](repo://p/u/compose/b/u/sketchpad/f/tailwind.config.ts/s/Configuration)
// Tailwind CSS configuration extending the shared compose preset for the sketchpad application.
// Configuration MUST use the shared tailwindConfig preset from @elements/ui.

import { tailwindConfig } from "@elements/ui";
import type { Config } from "tailwindcss";

/**
 * Tailwind CSS configuration with content paths and shared preset.
// [👤compose🖱️sketchpad⚙️tailwindconfig🔖configuration🪨config](repo://p/u/compose/b/u/sketchpad/f/tailwind.config.ts/s/Configuration/d/i/config)
 * Config MUST include content glob patterns and the tailwindConfig preset.
 **/
const config: Pick<Config, "content" | "presets"> = {
  content: ["./**/*.{ts,tsx,mdx}"],
  presets: [tailwindConfig],
};

// Default export of the Tailwind CSS configuration.
// Export MUST be the config object.
export default config;
// #endregion 🔖Configuration

