// Internationalization setup and translation utilities for the UI.

// #endregion 🔖Header

// #region 🔖I18n
// [👤compose📚js💻i18n🔖i18n](repo://p/u/compose/b/l/js/f/i18n.ts/s/I18n)
// Initializes i18next with language detection, React bindings and expertise-aware label hooks.
// MUST fall back to English when the detected language is unavailable.

import { i18next as i18n, initReactI18next, LanguageDetector } from "../../elements/ui";
import de from "./sketchpad/locales/de.json?raw";
import en from "./sketchpad/locales/en.json?raw";

// Re-export generic i18n primitives from @elements/ui
export { Expertise, setExpertiseProvider, useTranslatedHotkey as useHotkey, useLabel } from "../../elements/ui";

i18n
  .use(LanguageDetector)
  .use(initReactI18next)
  .init({
    resources: {
      en: { translation: JSON.parse(en) },
      de: { translation: JSON.parse(de) },
    },
    fallbackLng: "en",
    returnObjects: true,
    interpolation: {
      escapeValue: false,
    },
    react: {
      useSuspense: false,
      bindI18n: "languageChanged",
      bindI18nStore: "added removed",
    },
  });

export default i18n;

