// #endregion Header

// #region Imports

import { CloseIcon, PauseIcon, PlayIcon, RecordIcon, SkipBackIcon, SkipForwardIcon, StopIcon } from "@semio-tech/compose-assets";
import { guid, Guid } from "@semio-tech/compose-js/compose";
import { createContext, FC, ReactNode, useCallback, useContext, useEffect, useState } from "react";
import { Button, Slider } from "../../../elements/ui";
import { Mode } from "./shared";
import { useAddFooterItem, useMode, useRemoveFooterItem } from "./Sketchpad";

// #endregion Imports

// #region Components

// #region Tutorial Controls

// [👤compose📚js🗃️sketchpad💻tutorialstsx🔖components](composerepo://section/COMPOSE/JS/SKETCHPAD/TUTORIALS.TSX/COMPONENTS)
// Tutorial playback controls MUST render in the footer during active tutorials.

/**
 * Footer controls component for tutorial playback.
 * [👤compose📚js🗃️sketchpad💻tutorials🔖components🔖tutorialcontrols🪨tutorialcontrols](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Tutorials.tsx/s/Components/s/Tutorial%20Controls/d/i/TutorialControls)
 **/
export const TutorialControls: FC = () => {
  const addFooterItem = useAddFooterItem();
  const removeFooterItem = useRemoveFooterItem();
  const isTutorialActive = useIsTutorialActive();
  useEffect(() => {
    if (isTutorialActive) {
      addFooterItem({
        id: "tutorial-controls",
        content: <TutorialControlsContent />,
        className: "aspect-auto",
        order: 100,
      });
    } else {
      removeFooterItem("tutorial-controls");
    }
    return () => removeFooterItem("tutorial-controls");
  }, [isTutorialActive, addFooterItem, removeFooterItem]);
  return null;
};

/** TutorialControlsContent holds the data fields for a TutorialControlsContent record.
// [👤compose📚js🗃️sketchpad💻tutorials🔖components🔖tutorialcontrols🪨tutorialcontrolscontent](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Tutorials.tsx/s/Components/s/Tutorial%20Controls/d/i/TutorialControlsContent)
/**
 * [👤compose📚js🗃️sketchpad💻tutorials🔖components🔖tutorialcontrols🪨tutorialcontrolscontent](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Tutorials.tsx/s/Components/s/Tutorial%20Controls/d/i/TutorialControlsContent)
 **/
const TutorialControlsContent: FC = () => {
  const store = useTutorialStore();
  const tutorial = useActiveTutorial();
  const playbackState = usePlaybackState();
  const progress = useTutorialProgress();
  const currentMilestone = useCurrentMilestone();
  if (!tutorial) return null;
  const isPlaying = playbackState === TutorialPlaybackState.PLAYING;
  const isPaused = playbackState === TutorialPlaybackState.PAUSED;
  const isCompleted = playbackState === TutorialPlaybackState.COMPLETED;
  return (
    <div className="flex items-center gap-single px-2">
      <Button id="compose.sketchpad.tutorial.controls.stop" variant="ghost" onClick={() => store.stopTutorial()} className="size-tiny p-0">
        <CloseIcon className="size-tiny" />
      </Button>
      <div className="flex items-center gap-single">
        <Button id="compose.sketchpad.tutorial.controls.previous" variant="ghost" onClick={() => store.previousMilestone()} disabled={progress.current === 0} className="size-tiny p-0">
          <SkipBackIcon className="size-tiny" />
        </Button>
        <Button
          id="compose.sketchpad.tutorial.controls.playPause"
          variant="ghost"
          onClick={() => {
            if (isPlaying) {
              store.pauseTutorial();
            } else if (isPaused) {
              store.resumeTutorial();
            } else if (isCompleted) {
              store.startTutorial(tutorial);
            }
          }}
          className="size-tiny p-0"
        >
          {isPlaying ? <PauseIcon className="size-tiny" /> : <PlayIcon className="size-tiny" />}
        </Button>
        <Button id="compose.sketchpad.tutorial.controls.next" variant="ghost" onClick={() => store.nextMilestone()} disabled={progress.current >= progress.total - 1} className="size-tiny p-0">
          <SkipForwardIcon className="size-tiny" />
        </Button>
      </div>
      <div className="flex-1 min-w-[200px] max-w-[400px]">
        <div className="flex items-center gap-single">
          <Slider id="tutorial-progress" value={[progress.current]} min={0} max={Math.max(progress.total - 1, 0)} step={1} onValueChange={(value) => store.goToMilestone(value[0])} className="flex-1" />
          <span className="text-xs tabular-nums">
            {progress.current + 1}/{progress.total}
          </span>
        </div>
        {currentMilestone && <div className="text-xs truncate text-muted mt-1">{currentMilestone.title}</div>}
      </div>
      <div className="text-xs text-muted">{tutorial.name}</div>
    </div>
  );
};

// #endregion Tutorial Controls

// #region Recording Controls

// [👤compose📚js🗃️sketchpad💻tutorialstsx🔖components🔖recordingcontrols](composerepo://section/COMPOSE/JS/SKETCHPAD/TUTORIALS.TSX/COMPONENTS/RECORDING-CONTROLS)
// Recording controls MUST render in the footer during active recording in dev mode.

/**
 * Footer controls component for tutorial recording.
 * [👤compose📚js🗃️sketchpad💻tutorials🔖components🔖tutorialcontrols🔖recordingcontrols🪨recordingcontrols](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Tutorials.tsx/s/Components/s/Tutorial%20Controls/s/Recording%20Controls/d/i/RecordingControls)
 **/
export const RecordingControls: FC = () => {
  const addFooterItem = useAddFooterItem();
  const removeFooterItem = useRemoveFooterItem();
  const [mode] = useMode();
  const recordingState = useRecordingState();
  const isRecordingActive = recordingState !== TutorialRecordingState.IDLE;

  useEffect(() => {
    if (mode !== Mode.DEV) {
      removeFooterItem("recording-controls");
      return;
    }
    if (isRecordingActive) {
      addFooterItem({
        id: "recording-controls",
        content: <RecordingControlsContent />,
        className: "aspect-auto",
        order: 1,
      });
    } else {
      removeFooterItem("recording-controls");
    }
    return () => {
      removeFooterItem("recording-controls");
    };
  }, [mode, isRecordingActive, addFooterItem, removeFooterItem]);
  return null;
};

/** RecordingControlsContent holds the data fields for a RecordingControlsContent record.
// [👤compose📚js🗃️sketchpad💻tutorials🔖components🔖tutorialcontrols🔖recordingcontrols🪨recordingcontrolscontent](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Tutorials.tsx/s/Components/s/Tutorial%20Controls/s/Recording%20Controls/d/i/RecordingControlsContent)
/**
 * [👤compose📚js🗃️sketchpad💻tutorials🔖components🔖recordingcontrols🪨recordingcontrolscontent](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Tutorials.tsx/s/Components/s/Recording%20Controls/d/i/RecordingControlsContent)
 **/
const RecordingControlsContent: FC = () => {
  const store = useTutorialStore();
  const recordingState = useRecordingState();
  const activeRecording = useActiveRecording();
  const isRecording = recordingState === TutorialRecordingState.RECORDING;
  const isPaused = recordingState === TutorialRecordingState.PAUSED;
  const handleStop = () => {
    const recording = store.stopRecording();
    if (recording) {
      store.downloadRecording(recording);
    }
  };
  return (
    <div className="flex items-center gap-single px-2">
      <div className="flex items-center gap-single">
        <div className={`size-dot rounded-full ${isRecording ? "bg-red-500 animate-pulse" : "bg-gray-500"}`} />
        <span className="text-xs">REC</span>
      </div>
      <Button
        id="compose.sketchpad.recording.controls.playPause"
        variant="ghost"
        onClick={() => {
          if (isRecording) {
            store.pauseRecording();
          } else if (isPaused) {
            store.resumeRecording();
          }
        }}
        className="size-tiny p-0"
      >
        {isRecording ? <PauseIcon className="size-tiny" /> : <PlayIcon className="size-tiny" />}
      </Button>
      <Button id="compose.sketchpad.recording.controls.stop" variant="ghost" onClick={handleStop} className="size-tiny p-0">
        <StopIcon className="size-tiny" />
      </Button>
      {activeRecording && <div className="text-xs text-muted">{activeRecording.name}</div>}
    </div>
  );
};

// #endregion Recording Controls

// #region Record Button

// [👤compose📚js🗃️sketchpad💻tutorialstsx🔖components🔖recordbutton](composerepo://section/COMPOSE/JS/SKETCHPAD/TUTORIALS.TSX/COMPONENTS/RECORD-BUTTON)
// Record button MUST toggle recording in the footer when in dev mode.

/**
 * Footer button component toggling tutorial recording.
 * [👤compose📚js🗃️sketchpad💻tutorials🔖components🔖tutorialcontrols🔖recordbutton🪨recordbutton](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Tutorials.tsx/s/Components/s/Tutorial%20Controls/s/Record%20Button/d/i/RecordButton)
 **/
export const RecordButton: FC = () => {
  const addFooterItem = useAddFooterItem();
  const removeFooterItem = useRemoveFooterItem();
  const [mode] = useMode();
  const isRecording = useIsRecording();
  const store = useTutorialStore();
  useEffect(() => {
    if (mode !== Mode.DEV) {
      removeFooterItem("record-button");
      return;
    }
    addFooterItem({
      id: "record-button",
      content: (
        <Button
          id="footer-record-button"
          variant="ghost"
          onClick={() => {
            if (isRecording) {
              store.stopRecording();
            } else {
              store.startRecording("New Recording", undefined);
            }
          }}
          className={isRecording ? "text-red-500 h-small w-small p-0" : "h-small w-small p-0"}
        >
          <RecordIcon className={isRecording ? "fill-current size-tiny" : "size-tiny"} />
        </Button>
      ),
      order: 0,
    });
    return () => {
      removeFooterItem("record-button");
    };
  }, [mode, isRecording, store, addFooterItem, removeFooterItem]);
  return null;
};

// #endregion Record Button

// #region Tutorial Overlay

// [👤compose📚js🗃️sketchpad💻tutorialstsx🔖components🔖tutorialoverlay](composerepo://section/COMPOSE/JS/SKETCHPAD/TUTORIALS.TSX/COMPONENTS/TUTORIAL-OVERLAY)
// Tutorial overlay MUST render focus highlights and cursor animations during playback.

/**
 * Overlay component rendering focus highlights and animated cursor.
 * [👤compose📚js🗃️sketchpad💻tutorials🔖components🔖tutorialcontrols🔖tutorialoverlay🪨tutorialoverlay](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Tutorials.tsx/s/Components/s/Tutorial%20Controls/s/Tutorial%20Overlay/d/i/TutorialOverlay)
 **/
export const TutorialOverlay: FC = () => {
  const isTutorialActive = useIsTutorialActive();
  const currentMilestone = useCurrentMilestone();
  const playbackTime = usePlaybackTime();
  const [cursorPosition, setCursorPosition] = useState<{ x: number; y: number } | null>(null);
  useEffect(() => {
    if (!currentMilestone?.cursorAnimation) {
      setCursorPosition(null);
      return;
    }
    const animation = currentMilestone.cursorAnimation;
    const progress = Math.min(playbackTime / animation.duration, 1);
    const x = animation.startX + (animation.endX - animation.startX) * progress;
    const y = animation.startY + (animation.endY - animation.startY) * progress;
    setCursorPosition({ x, y });
  }, [currentMilestone, playbackTime]);
  if (!isTutorialActive || !currentMilestone) return null;
  return (
    <>
      {currentMilestone.focusElement && <FocusOverlay focusElement={currentMilestone.focusElement} />}
      {cursorPosition && <AnimatedCursor position={cursorPosition} action={currentMilestone.cursorAnimation?.action} />}
      <MilestoneTooltip milestone={currentMilestone} />
    </>
  );
};

/**
 * FocusOverlayProps holds the data fields for a FocusOverlayProps record.
 * [👤compose📚js🗃️sketchpad💻tutorials🔖components🔖tutorialcontrols🔖tutorialoverlay✂️focusoverlay](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Tutorials.tsx/s/Components/s/Tutorial%20Controls/s/Tutorial%20Overlay/d/i/FocusOverlay)
 **/
interface FocusOverlayProps {
  focusElement: {
    selector: string;
    highlightMode: "dim" | "spotlight" | "pulse";
  };
}

// [👤compose📚js🗃️sketchpad💻tutorials🔖components🔖tutorialoverlay🪨focusoverlay](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Tutorials.tsx/s/Components/s/Tutorial%20Overlay/d/i/FocusOverlay)
/**
 * [👤compose📚js🗃️sketchpad💻tutorials🔖components🔖tutorialoverlay🪨focusoverlay](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Tutorials.tsx/s/Components/s/Tutorial%20Overlay/d/i/FocusOverlay)
 * FocusOverlay holds the data fields for a FocusOverlay record.
 **/
const FocusOverlay: FC<FocusOverlayProps> = ({ focusElement }) => {
  const [rect, setRect] = useState<DOMRect | null>(null);
  useEffect(() => {
    const element = document.querySelector(focusElement.selector);
    if (!element) return;
    const updateRect = () => {
      setRect(element.getBoundingClientRect());
    };
    updateRect();
    const observer = new ResizeObserver(updateRect);
    observer.observe(element);
