  id: Guid;
  title: string;
  description?: string;
  commandPattern?: {
    command: string;
    origin?: string;
    argsPattern?: any;
  };
  focusElement?: {
    selector: string;
    highlightMode: "dim" | "spotlight" | "pulse";
  };
  cursorAnimation?: {
    startX: number;
    startY: number;
    endX: number;
    endY: number;
    duration: number;
    action?: "click" | "drag" | "hover";
  };
  audioUrl?: string;
  videoUrl?: string;
  duration?: number;
  canSkip: boolean;
  order: number;
