/**
 * Returns an object of command functions for sending TypeApp XState events.
 *MUST return no-op functions when no kit or type scope is available.
 * [👤compose📚js🗃️sketchpad💻type🔖imports🔖xstatehooks🛠️usetypeappcommands](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Type.tsx/s/Imports/s/XState%20Hooks/d/i/useTypeAppCommands)
 **/
export function useTypeAppCommands(id?: TypeAppId) {
  const actor = useSketchpadActor();
  const kitScope = useKitScope();
  const typeScope = useTypeScope();
  const kitGuid = kitScope?.guid ?? id?.kit ?? "";
  const typeGuid = typeScope?.guid ?? id?.type ?? "";

  return useMemo(() => {
    const noOp = () => {};
    if (!kitGuid || !typeGuid) {
      return {
        startTransaction: noOp,
        finalizeTransaction: noOp,
        abortTransaction: noOp,
        undo: noOp,
        redo: noOp,
        selectAll: noOp,
        deselectAll: noOp,
        togglePanel: noOp,
        setCamera: noOp,
        focusPort: noOp,
        clearFocus: noOp,
        setActiveTool: noOp,
        selectConnector: noOp,
        deselectConnector: noOp,
        selectModel: noOp,
        deselectModel: noOp,
        hoverPort: noOp,
        hoverModel: noOp,
        clearHover: noOp,
        setSelectedModel: noOp,
        addModelTag: noOp,
        removeModelTag: noOp,
        clearModelTags: noOp,
        setModelTags: noOp,
        execute: noOp,
      };
    }

    return {
