              applyDiff({
                models: {
                  removed: type.models.map((model: any) => model.guid),
                  added: arrayMove(type.models, oldIndex, newIndex),
                },
              });
            }}
          >
            {(model, index) => {
              const isSelected = selection?.models?.includes(model.guid) || false;
              const isHovered = hover?.model === model.guid;
