                    if (!setSelection) return;
                    const compositionKind = resolveSelectionCompositionKind(activeTool, {
                      shiftKey: e.shiftKey,
                      altKey: e.altKey,
                      ctrlKey: e.ctrlKey,
                      metaKey: e.metaKey,
                    });
                    setSelection({
                      ...(selection || {}),
                      models: applySelectionComposition(selection?.models, [model.guid], compositionKind),
                      connectors: compositionKind === "replace" ? [] : selection?.connectors || [],
                    });
                  }}
                >
                  <TreeItem
                    key={`model-${index}`}
                    id="compose.sketchpad.app.type.model"
                    label={model.url}
                    sortable={true}
                    sortableId={`model-${index}`}
                    isDragHandle={true}
                    className={`${isSelected ? "bg-accent/20" : ""} ${isHovered ? "bg-hover" : ""}`}
                    actions={[
                      {
                        icon: <RemoveIcon />,
                        onClick: () => {
                          const origin = "compose.sketchpad.app.type.panel.details.models.remove";
                          applyDiff({
                            models: {
