                    <TreeRow>
                      <Input
                        id="compose.sketchpad.app.type.panel.details.section.models.tags"
                        value={(model.tags || []).join(", ")}
                        placeholderId="compose.sketchpad.app.type.modelTagsPlaceholder.label"
                        onChange={(e) => {
                          updateModel(model.guid, {
                            tags: e.target.value
                              .split(",")
                              .map((tag) => tag.trim())
                              .filter((tag) => tag),
                          });
                        }}
                        showLabel
                      />
                    </TreeRow>
                  </TreeItem>
                </div>
              );
            }}
          </SortableTreeItems>
        )}
      </TreeItem>
    </>
  );
};

