                label={item.name}
                sortable={true}
                sortableId={`author-${index}`}
                isDragHandle={true}
                actions={[
                  {
                    icon: <RemoveIcon />,
                    onClick: () => {
                      updateAuthors((type.authors || []).filter((_, i: number) => i !== index).map((a) => a.guid));
