  const tooltip = useTooltip();
  const kitCommands = useKitCommands();
  const type = useType(undefined, undefined, true) as Type;

  const connectors = type.connectors?.filter((p) => connectorGuids.includes(p.guid)) || [];

  if (connectors.length === 0) {
    return (
      <TreeRow>
        <p className="text-sm text-muted-foreground">{useLabel("compose.sketchpad.app.type.connectorsNotFound")}</p>
      </TreeRow>
    );
  }

  const getCommonValue = <T,>(getter: (connector: any) => T | undefined): T | undefined => {
    const values = connectors.map(getter).filter((v) => v !== undefined);
    if (values.length === 0) return undefined;
    const firstValue = values[0];
    return values.every((v) => JSON.stringify(v) === JSON.stringify(firstValue)) ? firstValue : undefined;
  };

  const updatePorts = (origin: string, connectorDiff: any) => {
    connectors.forEach((connector) => {
      const diff: any = { ...connectorDiff };
      if (connectorDiff.point) {
        diff.point = {};
        if (connectorDiff.point.x !== undefined) diff.point.x = connectorDiff.point.x - connector.point.x;
        if (connectorDiff.point.y !== undefined) diff.point.y = connectorDiff.point.y - connector.point.y;
        if (connectorDiff.point.z !== undefined) diff.point.z = connectorDiff.point.z - connector.point.z;
      }
      if (connectorDiff.direction) {
        diff.direction = {};
        if (connectorDiff.direction.x !== undefined) diff.direction.x = connectorDiff.direction.x - connector.direction.x;
        if (connectorDiff.direction.y !== undefined) diff.direction.y = connectorDiff.direction.y - connector.direction.y;
        if (connectorDiff.direction.z !== undefined) diff.direction.z = connectorDiff.direction.z - connector.direction.z;
      }
      kitCommands?.updateType(type.guid, {
        connectors: {
          updated: [{ connector: { guid: connector.guid }, diff }],
        },
      });
    });
  };

  const commonPort = getCommonValue((p) => p.port);
  const commonT = getCommonValue((p) => p.t);
  const commonPointX = getCommonValue((p) => p.point?.x);
  const commonPointY = getCommonValue((p) => p.point?.y);
  const commonPointZ = getCommonValue((p) => p.point?.z);
  const commonDirectionX = getCommonValue((p) => p.direction?.x);
  const commonDirectionY = getCommonValue((p) => p.direction?.y);
  const commonDirectionZ = getCommonValue((p) => p.direction?.z);

  return (
    <>
      <TreeRow>
        <Input
          lazy
          id="compose.sketchpad.app.type.panel.details.section.connectors.port"
          value={commonPort || ""}
          placeholderId={commonPort === undefined ? "compose.sketchpad.common.mixedValues" : "compose.sketchpad.app.type.connectorPortPlaceholder.label"}
          onLazyChange={(value) => updatePorts("compose.sketchpad.app.type.panel.details.section.connectors.port", { port: value })}
          showLabel
        />
      </TreeRow>
      <TreeRow>
        <Slider
          id="compose.sketchpad.app.type.panel.details.section.connectors.t"
          value={[commonT ?? 0]}
          onValueChange={([value]) => {
            updatePorts("compose.sketchpad.app.type.panel.details.section.connectors.t", { t: value });
          }}
          min={0}
          max={1}
          step={0.01}
          showLabel
        />
      </TreeRow>
      <TreeItem id="compose.sketchpad.app.type.connectorPoint">
        <TreeRow>
          <Stepper
            id="compose.sketchpad.app.type.panel.details.section.connectors.point.x"
            value={commonPointX}
            onChange={(value: number) => {
              updatePorts("compose.sketchpad.app.type.panel.details.section.connectors.point.x", { point: { x: value } });
            }}
            step={0.1}
          />
        </TreeRow>
        <TreeRow>
          <Stepper
            id="compose.sketchpad.app.type.panel.details.section.connectors.point.y"
            value={commonPointY}
            onChange={(value: number) => {
              updatePorts("compose.sketchpad.app.type.panel.details.section.connectors.point.y", { point: { y: value } });
            }}
            step={0.1}
          />
        </TreeRow>
        <TreeRow>
          <Stepper
            id="compose.sketchpad.app.type.panel.details.section.connectors.point.z"
            value={commonPointZ}
            onChange={(value: number) => {
              updatePorts("compose.sketchpad.app.type.panel.details.section.connectors.point.z", { point: { z: value } });
            }}
            step={0.1}
          />
        </TreeRow>
      </TreeItem>
      <TreeItem id="compose.sketchpad.app.type.connectorDirection">
        <TreeRow>
          <Stepper
            id="compose.sketchpad.app.type.panel.details.section.connectors.direction.x"
            value={commonDirectionX}
            onChange={(value: number) => {
              updatePorts("compose.sketchpad.app.type.panel.details.section.connectors.direction.x", { direction: { x: value } });
            }}
            step={0.1}
          />
        </TreeRow>
        <TreeRow>
          <Stepper
            id="compose.sketchpad.app.type.panel.details.section.connectors.direction.y"
            value={commonDirectionY}
            onChange={(value: number) => {
              updatePorts("compose.sketchpad.app.type.panel.details.section.connectors.direction.y", { direction: { y: value } });
            }}
            step={0.1}
          />
        </TreeRow>
        <TreeRow>
          <Stepper
            id="compose.sketchpad.app.type.panel.details.section.connectors.direction.z"
            value={commonDirectionZ}
            onChange={(value: number) => {
              updatePorts("compose.sketchpad.app.type.panel.details.section.connectors.direction.z", { direction: { z: value } });
            }}
            step={0.1}
          />
        </TreeRow>
      </TreeItem>
    </>
  );
};

