// Home app plugin and event handler registration MUST initialize XState context.

/** createDefaultHomeState holds the data fields for a createDefaultHomeState record.
 **/
// [👤compose📚js🗃️sketchpad💻home🔖imports🔖types🔖homeapppluginregistration🪨createdefaulthomestate](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Home.tsx/s/Imports/s/Types/s/Home%20App%20Plugin%20Registration/d/i/createDefaultHomeState)
/**
 * [👤compose📚js🗃️sketchpad💻home🔖homeapppluginregistration🪨createdefaulthomestate](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Home.tsx/s/Home%20App%20Plugin%20Registration/d/i/createDefaultHomeState)
 **/
const createDefaultHomeState = (): HomeState => ({
  panelVisibility: { ...EMPTY_PANEL_VISIBILITY },
  selection: undefined,
  hover: undefined,
  sortColumn: undefined,
  sortDirection: undefined,
  loadingKits: [],
});

/**
 * [👤compose📚js🗃️sketchpad💻home🔖imports🔖types🔖homeapppluginregistration🪨homeappplugin](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Home.tsx/s/Imports/s/Types/s/Home%20App%20Plugin%20Registration/d/i/homeAppPlugin)
 * homeAppPlugin holds the data fields for a homeAppPlugin record.
 **/
const homeAppPlugin: AppPlugin = {
  id: "home",
  namespace: "HOME",
  machine: {
    actions: {},
    guards: {},
    eventHandlers: {},
    selectors: {},
    createDefaultState: createDefaultHomeState,
  },
};

if (typeof window !== "undefined") {
  registerAppPlugin(homeAppPlugin);

  registerStandardAppEventHandlers({ namespace: "HOME", appKey: "homeApp", createDefaultState: createDefaultHomeState }, (event) => ({ kits: event.kits }));

  registerEventHandler("HOME.SET_SORT", {
    action: (context: any, event: any) => ({
      homeApp: { ...context.homeApp, sortColumn: event.column, sortDirection: event.direction },
    }),
  });

  registerEventHandler("HOME.SELECT_KIT", {
    action: (context: any, event: any) => {
      const kits = context.homeApp.selection?.kits || [];
      if (kits.includes(event.guid)) return {};
      return { homeApp: { ...context.homeApp, selection: { kits: [...kits, event.guid] } } };
    },
  });

  registerEventHandler("HOME.DESELECT_KIT", {
    action: (context: any, event: any) => {
      const kits = context.homeApp.selection?.kits || [];
      return { homeApp: { ...context.homeApp, selection: { kits: kits.filter((k: Guid) => k !== event.guid) } } };
    },
  });
}

