// [👤compose📚js🗃️sketchpad💻home🔖details🪨multiplekitssection](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Home.tsx/s/Details/d/i/MultipleKitsSection)
/**
 * [👤compose📚js🗃️sketchpad💻home🔖canvas🔖panels🔖right🔖details🪨multiplekitssection](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Home.tsx/s/Canvas/s/Panels/s/Right/s/Details/d/i/MultipleKitsSection)
 * MultipleKitsSection holds the data fields for a MultipleKitsSection record.
 **/
const MultipleKitsSection: FC<{ kitIds: string[] }> = ({ kitIds }) => {
  const kitShallows = useKitShallows();
  const kits = kitIds.map((id) => kitShallows.find((k) => k.guid === id)).filter((k) => k !== undefined) as KitShallow[];

  const getCommonValue = <T,>(getter: (kit: KitShallow) => T): T | undefined => {
    if (kits.length === 0) return undefined;
    const firstValue = getter(kits[0]);
    const allSame = kits.every((kit) => getter(kit) === firstValue);
    return allSame ? firstValue : undefined;
  };

  const commonName = getCommonValue((k) => k.name);
  const commonVersion = getCommonValue((k) => k.version);
  const commonDescription = getCommonValue((k) => k.description);
  const commonIcon = getCommonValue((k) => k.icon);
  const commonImage = getCommonValue((k) => k.image);

  return (
    <>
      <TreeRow>
        <Input id="compose.sketchpad.app.home.panel.details.kits.name" value={commonName || ""} placeholder={commonName === undefined ? useLabel("compose.sketchpad.common.mixedValues") : undefined} readOnly showLabel />
      </TreeRow>
      <TreeRow>
        <Input
          id="compose.sketchpad.app.home.panel.details.kits.version"
          value={commonVersion || ""}
          placeholder={commonVersion === undefined ? useLabel("compose.sketchpad.common.mixedValues") : useLabel("compose.sketchpad.app.kit.versionPlaceholder.label")}
          readOnly
          showLabel
        />
      </TreeRow>
      <TreeRow>
        <Textarea
          id="compose.sketchpad.app.home.panel.details.kits.description"
          value={commonDescription || ""}
          placeholder={commonDescription === undefined ? useLabel("compose.sketchpad.common.mixedValues") : useLabel("compose.sketchpad.app.kit.descriptionPlaceholder.label")}
          readOnly
          showLabel
        />
      </TreeRow>
      <TreeRow>
        <Input
          id="compose.sketchpad.app.home.panel.details.kits.icon"
          value={commonIcon || ""}
          placeholder={commonIcon === undefined ? useLabel("compose.sketchpad.common.mixedValues") : useLabel("compose.sketchpad.app.kit.iconPlaceholder.label")}
          readOnly
          showLabel
        />
      </TreeRow>
      <TreeRow>
        <Input
          id="compose.sketchpad.app.home.panel.details.kits.image"
          value={commonImage || ""}
          placeholder={commonImage === undefined ? useLabel("compose.sketchpad.common.mixedValues") : useLabel("compose.sketchpad.app.kit.imagePlaceholder.label")}
          readOnly
          showLabel
        />
      </TreeRow>
    </>
  );
};

