type KitKind = "temporary" | "local" | "remote";

// [👤compose📚js🗃️sketchpad💻home🔖app🪨hometoolbarfilters](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Home.tsx/s/App/d/i/HomeToolbarFilters)
/**
 * [👤compose📚js🗃️sketchpad💻home🔖app🪨hometoolbarfilters](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Home.tsx/s/App/d/i/HomeToolbarFilters)
 * HomeToolbarFilters holds the data fields for a HomeToolbarFilters record.
 **/
const HomeToolbarFilters: FC = () => {
  const [searchParams, setSearchParams] = useSearchParams();
  const selectedKind = searchParams.get("kind") as KitKind | null;

  const toggleKind = (type: KitKind) => {
    const newParams = new URLSearchParams(searchParams);
    if (selectedKind === type) {
      newParams.delete("kind");
      newParams.delete("name");
      newParams.delete("version");
    } else {
      newParams.set("kind", type);
      newParams.delete("name");
      newParams.delete("version");
    }
    setSearchParams(newParams);
  };

  const labelTemporary = useLabel("compose.sketchpad.app.home.toolbar.showTemporary");
  const labelLocal = useLabel("compose.sketchpad.app.home.toolbar.showLocal");
  const labelRemote = useLabel("compose.sketchpad.app.home.toolbar.showRemote");

  return (
    <ToolbarGroup>
      <Toggle pressed={selectedKind === "temporary"} onPressedChange={() => toggleKind("temporary")} id="compose.sketchpad.app.home.toolbar.showTemporary" icon={<TemporaryKitIcon />} text={labelTemporary} />
      <Toggle pressed={selectedKind === "local"} onPressedChange={() => toggleKind("local")} id="compose.sketchpad.app.home.toolbar.showLocal" icon={<LocalKitIcon />} text={labelLocal} />
      <Toggle pressed={selectedKind === "remote"} onPressedChange={() => toggleKind("remote")} id="compose.sketchpad.app.home.toolbar.showRemote" icon={<RemoteKitIcon />} text={labelRemote} />
    </ToolbarGroup>
  );
};

// [👤compose📚js🗃️sketchpad💻home🔖app🪨hometoolbarcreate](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Home.tsx/s/App/d/i/HomeToolbarCreate)
