                          ))}
                        </div>
                      </Scrollable>
                    )}
                    <div className="flex items-center gap-single shrink-0 ml-auto">
                      {row.level === 0 && row.type !== "docs" && row.type !== "loading" && (
                        <Action
                          onClick={(e) => {
                            e.stopPropagation();
                            handleCreateVersion(row.name, row.type as KitKind);
                          }}
                          id={"compose.sketchpad.app.home.createVersion"}
                          icon={<AddIcon />}
                        />
                      )}
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </Scrollable>
      </div>
    );
  }

  return (
    <div
      className="flex flex-col h-full"
      onClick={(e: React.MouseEvent) => {
        if (e.target === e.currentTarget) {
          homeCommands.deselectAll("compose.sketchpad.app.home.canvas.table.deselect");
        }
      }}
    >
      <Table<TableRow>
        className="flex-1 min-h-0"
        columns={[
          ...(!selectedKind
            ? [
                {
                  id: "type",
                  header: (
                    <div className="inline-flex items-center gap-single">
                      <span>{useLabel("compose.sketchpad.app.home.kind")}</span>
                      <Toggle
                        kind="dropdown"
                        pressed={sortColumn === "type"}
                        value={sortColumn === "type" ? sortDirection : "asc"}
                        onValueChange={(value) => {
                          homeCommands.setSortColumn("compose.sketchpad.app.home.header.type.sortColumn", "type");
                          homeCommands.setSortDirection("compose.sketchpad.app.home.header.type.sortDirection", value as "asc" | "desc");
                        }}
                        items={[
                          { value: "asc", label: <SortAscendingIcon />, id: "compose.sketchpad.sort.ascending" },
                          { value: "desc", label: <SortDescendingIcon />, id: "compose.sketchpad.sort.descending" },
                        ]}
                        id={"compose.sketchpad.app.home.sortByType"}
                      />
                    </div>
                  ),
                  accessor: (row) => (
                    <>
                      {row.type === "temporary" && <TemporaryKitIcon />}
                      {row.type === "local" && <LocalKitIcon />}
                      {row.type === "remote" && <RemoteKitIcon />}
                      {row.type === "docs" && <DocumentIcon className="size-small" />}
                    </>
                  ),
                  width: "w-0 whitespace-nowrap",
                  headerClassName: "relative group w-0 whitespace-nowrap",
                } as TableColumn<TableRow>,
              ]
            : []),
          {
            id: "name",
            header: (
              <div className="flex items-center justify-between w-full">
                <span>{useLabel("compose.sketchpad.app.home.name")}</span>
                <Toggle
                  kind="dropdown"
                  pressed={sortColumn === "name"}
                  value={sortColumn === "name" ? sortDirection : "asc"}
                  onValueChange={(value) => {
                    homeCommands.setSortColumn("compose.sketchpad.app.home.header.name.sortColumn", "name");
                    homeCommands.setSortDirection("compose.sketchpad.app.home.header.name.sortDirection", value as "asc" | "desc");
                  }}
                  items={[
                    { value: "asc", label: <SortAscendingIcon />, id: "compose.sketchpad.sort.ascending" },
                    { value: "desc", label: <SortDescendingIcon />, id: "compose.sketchpad.sort.descending" },
                  ]}
                  id={"compose.sketchpad.app.home.sortByName"}
                />
              </div>
            ),
            accessor: (row) => (
              <div className={`flex items-center gap-single w-full ${row.isLoading ? "opacity-50 pointer-events-none" : ""}`} onClick={(e) => e.stopPropagation()}>
                <div className="flex items-center gap-single flex-1 min-w-0" style={{ paddingLeft: `calc(${row.level} * var(--size-small))` }}>
                  {row.hasChildren ? (
                    <Action
                      id={"compose.sketchpad.app.home.toggleRow"}
                      onClick={(e) => {
                        e.stopPropagation();
                        toggleRow(row.id);
                      }}
                      icon={row.isExpanded ? <ChevronDownIcon className="size-small" /> : <ChevronRightIcon className="size-small" />}
                    />
                  ) : (
                    <span className="size-small shrink-0" />
                  )}
                  <TableAvatar name={row.name} icon={row.type === "docs" ? row.icon : row.kit?.icon} />
                  <span className="text-left min-w-0 truncate">{row.name}</span>
                  {row.isLoading && <Spinner size="small" />}
                </div>
                {row.concepts && row.concepts.length > 0 && (
                  <Scrollable orientation="horizontal" className="shrink-0 min-w-0 max-w-[200px]">
                    <div className="flex items-center gap-single px-single h-medium w-fit">
                      {row.concepts.map((concept) => (
                        <Action key={concept} onClick={() => toggleConcept(concept)} id={`compose.sketchpad.app.home.row.concept.${concept}`} text={concept} className={selectedConcepts.includes(concept) ? "bg-active-base" : ""} />
                      ))}
                    </div>
                  </Scrollable>
                )}
                <div className="flex items-center gap-single shrink-0 ml-auto">
                  {row.level === 0 && row.type !== "docs" && row.type !== "loading" && (
                    <Action
                      onClick={(e) => {
                        e.stopPropagation();
                        handleCreateVersion(row.name, row.type as KitKind);
                      }}
                      id={"compose.sketchpad.app.home.createVersion"}
                      icon={<AddIcon />}
                    />
                  )}
                </div>
              </div>
            ),
            headerClassName: "relative group",
          },
          {
            id: "updatedAt",
            header: (
              <div className="flex items-center justify-between w-full">
                <span>{useLabel("compose.sketchpad.app.home.lastUpdated")}</span>
                <Toggle
                  kind="dropdown"
                  pressed={sortColumn === "updatedAt"}
                  value={sortColumn === "updatedAt" ? sortDirection : "asc"}
                  onValueChange={(value) => {
                    homeCommands.setSortColumn("compose.sketchpad.app.home.header.updatedAt.sortColumn", "updatedAt");
                    homeCommands.setSortDirection("compose.sketchpad.app.home.header.updatedAt.sortDirection", value as "asc" | "desc");
                  }}
                  items={[
                    { value: "asc", label: <SortAscendingIcon />, id: "compose.sketchpad.sort.ascending" },
                    { value: "desc", label: <SortDescendingIcon />, id: "compose.sketchpad.sort.descending" },
                  ]}
                  id={"compose.sketchpad.app.home.sortByUpdatedAt"}
                />
              </div>
            ),
            accessor: (row) => row.updatedAt,
            headerClassName: "relative group",
          },
          {
            id: "createdAt",
            header: (
              <div className="flex items-center justify-between w-full">
                <span>{useLabel("compose.sketchpad.app.home.created")}</span>
                <Toggle
                  kind="dropdown"
                  pressed={sortColumn === "createdAt"}
                  value={sortColumn === "createdAt" ? sortDirection : "asc"}
                  onValueChange={(value) => {
                    homeCommands.setSortColumn("compose.sketchpad.app.home.header.createdAt.sortColumn", "createdAt");
                    homeCommands.setSortDirection("compose.sketchpad.app.home.header.createdAt.sortDirection", value as "asc" | "desc");
                  }}
                  items={[
                    { value: "asc", label: <SortAscendingIcon />, id: "compose.sketchpad.sort.ascending" },
                    { value: "desc", label: <SortDescendingIcon />, id: "compose.sketchpad.sort.descending" },
                  ]}
                  id={"compose.sketchpad.app.home.sortByCreatedAt"}
                />
              </div>
            ),
            accessor: (row) => row.createdAt,
            headerClassName: "relative group",
          },
        ]}
        rowClassName={(row) => {
          if (!row.kit) return "";
          if (selection.includes(row.kit.guid)) return "";
          return hover?.kits?.includes(row.kit.guid) ? "bg-hover-base" : "";
        }}
        onRowMouseEnter={(row) => {
          if (!row.kit) {
            homeCommands.clearHover("compose.sketchpad.app.home.canvas.table.clearHover");
            return;
          }
          homeCommands.hoverKit("compose.sketchpad.app.home.canvas.table.hover", row.kit.guid);
        }}
        onRowMouseLeave={() => {
          homeCommands.clearHover("compose.sketchpad.app.home.canvas.table.clearHover");
        }}
        data={rows}
        onRowClick={(row, _, e) => {
          const isDocsRow = row.type === "docs";
          if (isDocsRow && row.docsPath) {
            navigate(`/${row.docsPath}`);
          } else if (row.kit) {
            handleRowClick(row.kit.guid, e);
          }
        }}
        onRowDoubleClick={(row) => {
          const isDocsRow = row.type === "docs";
          if (isDocsRow && row.docsPath) {
            navigate(`/${row.docsPath}`);
          } else if (row.kit) {
            navigateToKit(row.kit.guid);
          }
        }}
        rowKey={(row) => row.id}
        getRowId={(row) => row.kit?.guid || row.id}
        selectedRows={new Set(selection)}
        focusedItemId={focusedItemId}
        onFocusComplete={() => setFocusedItemId(undefined)}
        emptyMessage={useLabel("compose.sketchpad.app.home.noKits")}
        stickyHeader={true}
        headerClassName="sticky top-0 border-b border-element"
        hierarchical={true}
      />
    </div>
  );
};

// #region Multi-Window App

// [👤compose📚js🗃️sketchpad💻hometsx🔖app🔖multiwindowapp](repo://section/COMPOSE/JS/SKETCHPAD/HOME.TSX/APP/MULTI-WINDOW-APP)
// Multi-window app MUST orchestrate the Home canvas and layout.

/**
 * [👤compose📚js🗃️sketchpad💻home🔖imports🔖app🔖multiwindowapp🪨home](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Home.tsx/s/Imports/s/App/s/Multi-Window%20App/d/i/Home)
 * TableWindow holds the data fields for a TableWindow record.
 **/
const TableWindow = memo(() => {
  return <HomeTableContent />;
});
TableWindow.displayName = "TableWindow";

// [👤compose📚js🗃️sketchpad💻home🔖app🔖multiwindowapp🪨home](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Home.tsx/s/App/s/Multi-Window%20App/d/i/Home)
/**
 * [👤compose📚js🗃️sketchpad💻home🔖app🔖multiwindowapp🪨home](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Home.tsx/s/App/s/Multi-Window%20App/d/i/Home)
 * Home holds the data fields for a Home record.
 **/
const Home: FC = () => {
  const actor = useSketchpadActor();
  const appType = useAppType();
  const addSection = useAddPanelSection();
  const removeSection = useRemovePanelSection();
  const isMobile = useIsMobile();

  const homeState = useHome() as HomeState;
  const storedWindowLayout = homeState?.windowLayout;

  const lastLayoutRef = useRef<any>(null);

  useEffect(() => {
    if (appType !== "home") return;

    addSection("toolbar", {
      id: "compose.sketchpad.app.home.toolbar.filters",
      specificity: 20,
      order: 0,
      toolbarGroup: {
        id: "filter",
        labelId: "compose.sketchpad.toolbar.parent.filter",
        order: 20,
      },
      content: <HomeToolbarFilters />,
    });
    addSection("toolbar", {
      id: "compose.sketchpad.app.home.toolbar.create",
      specificity: 20,
      order: 0,
      toolbarGroup: {
        id: "create",
        labelId: "compose.sketchpad.toolbar.parent.create",
        order: 30,
      },
      content: <HomeToolbarCreate />,
    });

    return () => {
      removeSection("toolbar", "compose.sketchpad.app.home.toolbar.filters");
      removeSection("toolbar", "compose.sketchpad.app.home.toolbar.create");
    };
  }, [appType, addSection, removeSection]);

  // Add Settings and Chat as side panel tabs
  const addSidePanelTab = useAddSidePanelTab();
  const removeSidePanelTab = useRemoveSidePanelTab();

  useEffect(() => {
    if (appType !== "home") return;

    addSidePanelTab("right", {
      id: "compose.sketchpad.app.home.settings",
      icon: SettingsIcon,
      order: 100,
      content: () => (
        <TreeStateProvider>
          <Tree className="min-w-0 overflow-hidden p-double" sections={[{ id: "compose.sketchpad.app.home.settings.content", label: null, content: <SettingsContent /> }]} />
        </TreeStateProvider>
      ),
    });

    addSidePanelTab("right", {
      id: "compose.sketchpad.app.home.chat",
      icon: ChatIcon,
      order: 101,
      content: () => (
        <TreeStateProvider>
          <Tree className="min-w-0 overflow-hidden p-double" sections={[{ id: "compose.sketchpad.app.home.chat.content", label: null, content: <ChatPlaceholder /> }]} />
        </TreeStateProvider>
      ),
    });

    return () => {
      removeSidePanelTab("right", "compose.sketchpad.app.home.settings");
      removeSidePanelTab("right", "compose.sketchpad.app.home.chat");
    };
  }, [appType, addSidePanelTab, removeSidePanelTab]);

  const defaultLayout = useMemo(
    () => ({
      root: {
        type: "row",
        content: [
          {
            type: "stack",
            size: "100%",
            content: [
              {
                type: "component",
                componentName: HomeAppWindowKind.Table,
                title: "table",
                componentState: {},
              },
            ],
          },
        ],
      },
    }),
    [],
  );

  const windowLayout = useMemo(() => storedWindowLayout || defaultLayout, [storedWindowLayout, defaultLayout]);

  const windowConfig: AppWindowConfig = useMemo(
    () => ({
      windowKinds: [
        {
          id: HomeAppWindowKind.Table,
          label: "table",
          component: () => <TableWindow />,
        },
      ],
      defaultLayout,
    }),
    [defaultLayout],
  );

  const handleLayoutChange = useCallback(
    (config: any) => {
      const configStr = JSON.stringify(config);
      const lastStr = JSON.stringify(lastLayoutRef.current);
      if (configStr === lastStr) return;
    },
    [actor],
  );

  if (isMobile) {
    return (
      <HomeDropZone>
        <HomeTableContent />
      </HomeDropZone>
    );
  }

  return (
    <>
      <HomeFooter />
      <HomeDropZone>
        <Canvas id="compose.sketchpad.app.home.canvas">
          <LayoutCanvas windowConfig={windowConfig} layoutState={windowLayout} onLayoutChange={handleLayoutChange} />
        </Canvas>
      </HomeDropZone>
    </>
  );
};

