// MUST bridge sync document observation to XState machine events.

/**
 * Creates an XState callback actor that observes a sync map and sends SYNC_UPDATE events.
 * MUST observe the sync map deeply and send SYNC_UPDATE events on every change.
 * [👤compose📚js🗃️sketchpad💻shared🔖types🔖granularhooktypes🔖standardemptyconstants🔖enums🔖ports🔖fileprovider🔖appids🔖panel🔖appregistry🔖sketchpadstate🔖commands🔖store🔖completestate🔖window🔖tool🔖focus🔖footer🔖xstateintegration🔖xstatetypes🔖syncxstatebridge🛠️createsyncactor](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/shared.ts/s/Types/s/Granular%20Hook%20Types/s/Standard%20Empty%20Constants/s/Enums/s/Ports/s/File%20Provider/s/App%20IDs/s/Panel/s/App%20Registry/s/Sketchpad%20State/s/Commands/s/Store/s/Complete%20State/s/Window/s/Tool/s/Focus/s/Footer/s/XState%20Integration/s/XState%20Types/s/Y.js-XState%20Bridge/d/i/createSyncActor)
 **/
export function createSyncActor(syncMap: SyncMap<any>) {
  return fromCallback<{ type: "SYNC_UPDATE"; data: any }>(({ sendBack }: { sendBack: (event: { type: "SYNC_UPDATE"; data: any }) => void }) => {
    const observer = () => {
      sendBack({ type: "SYNC_UPDATE", data: syncMap.toJSON() });
    };

    observer();

    syncMap.observeDeep(observer);

    return () => {
      syncMap.unobserveDeep(observer);
    };
  });
}

/**
 * Creates an XState callback actor that observes a single field in a sync map.
 * MUST observe a specific field in the sync map and send SYNC_FIELD_UPDATE events.
 * [👤compose📚js🗃️sketchpad💻shared🔖types🔖granularhooktypes🔖standardemptyconstants🔖enums🔖ports🔖fileprovider🔖appids🔖panel🔖appregistry🔖sketchpadstate🔖commands🔖store🔖completestate🔖window🔖tool🔖focus🔖footer🔖xstateintegration🔖xstatetypes🔖syncxstatebridge🛠️createfieldsyncactor](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/shared.ts/s/Types/s/Granular%20Hook%20Types/s/Standard%20Empty%20Constants/s/Enums/s/Ports/s/File%20Provider/s/App%20IDs/s/Panel/s/App%20Registry/s/Sketchpad%20State/s/Commands/s/Store/s/Complete%20State/s/Window/s/Tool/s/Focus/s/Footer/s/XState%20Integration/s/XState%20Types/s/Y.js-XState%20Bridge/d/i/createFieldSyncActor)
 **/
export function createFieldSyncActor(syncMap: SyncMap<any>, field: string) {
  return fromCallback<{ type: "SYNC_FIELD_UPDATE"; field: string; value: any }>(({ sendBack }: { sendBack: (event: { type: "SYNC_FIELD_UPDATE"; field: string; value: any }) => void }) => {
    const observer = (events: SyncMapEvent[]) => {
      for (const event of events) {
        if (event.keysChanged.has(field)) {
          sendBack({ type: "SYNC_FIELD_UPDATE", field, value: syncMap.get(field) });
        }
      }
    };

    sendBack({ type: "SYNC_FIELD_UPDATE", field, value: syncMap.get(field) });

    syncMap.observe(observer as any);

    return () => {
      syncMap.unobserve(observer as any);
    };
  });
}

/**
