// #endregion Header

// #region Imports

import { AddIcon, AwardIcon, ChatIcon, CodeIcon, HandIcon, IntersectIcon, MonitorIcon, MoonIcon, MousePointerIcon, RemoveIcon, SettingsIcon, SunIcon, TutorialIcon, UserIcon } from "@semio-tech/compose-assets";
import { guid, Guid, Kit, Quality, QualityDiff, sumQualityInDesign } from "@semio-tech/compose-js/compose";
import React, { createContext, FC, memo, useCallback, useContext, useEffect, useMemo, useRef } from "react";
import type { Connection, DragEndEvent, Edge, Node, NodeTypes, ReactFlowInstance } from "../../../elements/ui";
import {
  Diagram as BaseDiagram,
  BasicChatPanel,
  calculateDiagramLayout,
  DiagramNode,
  DraggableAvatar,
  HoverCard,
  HoverCardContent,
  HoverCardTrigger,
  Input,
  PlaceholderDiagramNode,
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
  Textarea,
  Toggle,
  ToggleGroup,
  Tree,
  TreeContent,
  TreeItem,
  TreeRow,
  TreeStateProvider,
  useDraggable,
  useDroppable,
  useHotkeys,
  useTranslation,
} from "../../../elements/ui";
import { useLabel } from "../i18n";
import type { AppWindowConfig, HookNoSetResult, HookResult, KitCommandContext, KitDiffAppEdit, PanelDefinition, PanelVisibility, QualityAppId } from "./shared";
import {
  AppConfig,
  applySelectionComposition,
  AppPlugin,
  createPanelDefinition,
  Expertise,
  isSelectionToolKind,
  Mode,
  PanelKind,
  registerAppPlugin,
  registerEventHandler,
  resolveSelectionCompositionKind,
  Theme,
  ToolKind,
  toSelectionToolKind,
} from "./shared";
import type { CollaborativeKitStore, QualityStore, SketchpadStore } from "./Sketchpad";
import {
  Canvas,
  createDefaultQualityAppState,
  identitySelector,
  KitScopeProvider,
  LayoutCanvas,
  PlainKitDiffAppStore,
  QualityScopeProvider,
  registerQualityAppStoreFactory,
  useActiveInteraction,
  useAddPanelSection,
  useAddSidePanelTab,
  useAppType,
  useDevice,
  useExpertise,
  useKit,
  useKitScope,
  useLanguage,
  useMode,
  useQuality,
  useQualityScope,
  useRemovePanelSection,
  useRemoveSidePanelTab,
  useSketchpadCommands,
  useSketchpadStore,
  useSyncDeep,
  useTheme,
} from "./Sketchpad";

// #endregion Imports

// #region Types

// [👤compose📚js🗃️sketchpad💻qualitytsx🔖types](repo://section/COMPOSE/JS/SKETCHPAD/QUALITY.TSX/TYPES)
// Type definitions MUST declare quality app state, selections, and formula structures.

/**
 * Node in a formula graph with position, kind, and child references.
 * [👤compose📚js🗃️sketchpad💻quality🔖types🛠️formulanode](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Quality.tsx/s/Types/d/i/FormulaNode)
 **/
export interface FormulaNode {
  id: Guid;
  kind: "function" | "quality" | "variable" | "unit" | "value";
  name: string;
  children?: Guid[];
  x?: number;
  y?: number;
}

/**
 * Selected formula node IDs in the quality app.
 * [👤compose📚js🗃️sketchpad💻quality🔖types🛠️qualityappselection](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Quality.tsx/s/Types/d/i/QualityAppSelection)
 **/
export interface QualityAppSelection {
  formulaNodes?: Guid[];
}

/**
 * Diff for added and removed formula node selections.
 * [👤compose📚js🗃️sketchpad💻quality🔖types🛠️qualityappselectionformulanodesdiff](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Quality.tsx/s/Types/d/i/QualityAppSelectionFormulaNodesDiff)
 **/
export interface QualityAppSelectionFormulaNodesDiff {
  added?: Guid[];
  removed?: Guid[];
}

/**
 * Diff for quality app selection changes.
 * [👤compose📚js🗃️sketchpad💻quality🔖types🛠️qualityappselectiondiff](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Quality.tsx/s/Types/d/i/QualityAppSelectionDiff)
 **/
export interface QualityAppSelectionDiff {
  formulaNodes?: QualityAppSelectionFormulaNodesDiff;
}

/**
 * Fullscreen window state for the quality app panels.
 * [👤compose📚js🗃️sketchpad💻quality🔖types🛠️qualityappfullscreenwindow](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Quality.tsx/s/Types/d/i/QualityAppFullscreenWindow)
 **/
export enum QualityAppFullscreenWindow {
  None = "none",
  Formula = "formula",
  Diagram = "diagram",
}

/**
 * Window kind identifiers for quality app layout.
 * [👤compose📚js🗃️sketchpad💻quality🔖types🛠️qualityappwindowkind](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Quality.tsx/s/Types/d/i/QualityAppWindowKind)
 **/
export enum QualityAppWindowKind {
  Formula = "formula",
  Diagram = "diagram",
}

/**
 * Hover state tracking the currently hovered formula node.
 * [👤compose📚js🗃️sketchpad💻quality🔖types🛠️qualityapphover](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Quality.tsx/s/Types/d/i/QualityAppHover)
 **/
export interface QualityAppHover {
  formulaNode?: Guid;
}

/**
 * Diff describing partial quality app state changes.
 * [👤compose📚js🗃️sketchpad💻quality🔖types🛠️qualityappdiff](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Quality.tsx/s/Types/d/i/QualityAppDiff)
 **/
export interface QualityAppDiff {
  selection?: QualityAppSelectionDiff;
  hover?: QualityAppHover;
  fullscreenWindow?: QualityAppFullscreenWindow;
  panelVisibility?: Partial<PanelVisibility>;
  activeTool?: ToolKind;
  formulaNodes?: FormulaNode[];
  windowLayout?: any;
}

export interface QualityAppEdit extends KitDiffAppEdit<QualityAppSelectionDiff> {}

/**
 * Complete quality app state including selection, hover, formula nodes, and layout.
 * [👤compose📚js🗃️sketchpad💻quality🔖types🛠️qualityappstate](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Quality.tsx/s/Types/d/i/QualityAppState)
 **/
export interface QualityAppState {
  fullscreenWindow: QualityAppFullscreenWindow;
  panelVisibility: PanelVisibility;
  activeTool: ToolKind;
  selection?: QualityAppSelection;
  hover?: QualityAppHover;
  formulaNodes: FormulaNode[];
  windowLayout?: any;
}

/**
 * Context passed to quality app command handlers.
 * [👤compose📚js🗃️sketchpad💻quality🔖types🛠️qualityappcommandcontext](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Quality.tsx/s/Types/d/i/QualityAppCommandContext)
 **/
export interface QualityAppCommandContext extends KitCommandContext {
  qualityApp: QualityAppState;
  Guid: Guid;
}

/**
 * Result returned by quality app command handlers.
 * [👤compose📚js🗃️sketchpad💻quality🔖types🛠️qualityappcommandresult](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Quality.tsx/s/Types/d/i/QualityAppCommandResult)
 **/
export interface QualityAppCommandResult {
  diff?: QualityAppDiff;
  qualityDiff?: QualityDiff;
}

/**
 * Definition of a formula function with calculation and LaTeX rendering.
 * [👤compose📚js🗃️sketchpad💻quality🔖types🛠️formulafunction](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Quality.tsx/s/Types/d/i/FormulaFunction)
 **/
export interface FormulaFunction {
  name: string;
  category: "numeric" | "branching" | "data" | "text" | "comparison";
  arity: number | "variadic";
  icon?: string;
  description: string;
  calculate: (...operands: any[]) => any;
  toLatex: (...operands: string[]) => string;
}

// #endregion Types

// #region Functions

// [👤compose📚js🗃️sketchpad💻qualitytsx🔖functions](repo://section/COMPOSE/JS/SKETCHPAD/QUALITY.TSX/FUNCTIONS)
// Formula function definitions, parsing, and LaTeX conversion utilities MUST be declared here.

/**
 * Registry of available formula functions keyed by name.
 * [👤compose📚js🗃️sketchpad💻quality🔖functions🪨formulafunctions](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Quality.tsx/s/Functions/d/i/formulaFunctions)
 **/
export const formulaFunctions: Record<string, FormulaFunction> = {
  Add: {
    name: "Add",
    category: "numeric",
    arity: "variadic",
    icon: "plus",
    description: "Add two or more numbers",
    calculate: (...operands: number[]) => operands.reduce((sum, val) => sum + val, 0),
    toLatex: (...operands: string[]) => operands.join(" + "),
  },
  Subtract: {
    name: "Subtract",
    category: "numeric",
    arity: 2,
    icon: "minus",
    description: "Subtract second number from first",
    calculate: (a: number, b: number) => a - b,
    toLatex: (a: string, b: string) => `${a} - ${b}`,
  },
  Multiply: {
    name: "Multiply",
    category: "numeric",
    arity: "variadic",
    icon: "times",
    description: "Multiply two or more numbers",
    calculate: (...operands: number[]) => operands.reduce((product, val) => product * val, 1),
    toLatex: (...operands: string[]) => operands.join(" \\times "),
  },
  Divide: {
    name: "Divide",
    category: "numeric",
    arity: 2,
