/**
 * Parses a formula string into an S-expression AST.
 *The formula string MUST be a valid S-expression.
 * [👤compose📚js🗃️sketchpad💻quality🔖functions🛠️parseformula](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Quality.tsx/s/Functions/d/i/parseFormula)
 **/
export function parseFormula(formula: string): any {
  const tokens = tokenizeFormula(formula);
  const [ast] = parseTokens(tokens, 0);
  return ast;
}

/** tokenizeFormula holds the data fields for a tokenizeFormula record.
 **/
// [👤compose📚js🗃️sketchpad💻quality🔖functions🛠️tokenizeformula](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Quality.tsx/s/Functions/d/i/tokenizeFormula)
/**
 * [👤compose📚js🗃️sketchpad💻quality🔖functions🪨tokenizeformula](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Quality.tsx/s/Functions/d/i/tokenizeFormula)
 **/
function tokenizeFormula(formula: string): string[] {
  const tokens: string[] = [];
  let current = "";
  let inString = false;

  for (let i = 0; i < formula.length; i++) {
    const char = formula[i];

    if (char === "'") {
      if (inString) {
        tokens.push(current + char);
        current = "";
        inString = false;
      } else {
        if (current.trim()) tokens.push(current.trim());
        current = char;
        inString = true;
      }
    } else if (inString) {
      current += char;
    } else if (char === "(") {
      if (current.trim()) tokens.push(current.trim());
      tokens.push("(");
      current = "";
    } else if (char === ")") {
      if (current.trim()) tokens.push(current.trim());
      tokens.push(")");
      current = "";
    } else if (char === " " || char === "\t" || char === "\n") {
      if (current.trim()) tokens.push(current.trim());
      current = "";
    } else {
      current += char;
    }
  }

  if (current.trim()) tokens.push(current.trim());
  return tokens;
}

/**
 * [👤compose📚js🗃️sketchpad💻quality🔖functions🛠️parsetokens](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Quality.tsx/s/Functions/d/i/parseTokens)
 * parseTokens holds the data fields for a parseTokens record.
 **/
function parseTokens(tokens: string[], start: number): [any, number] {
  if (start >= tokens.length) return [null, start];

  const token = tokens[start];

  if (token === "(") {
    const list: any[] = [];
    let i = start + 1;
    while (i < tokens.length && tokens[i] !== ")") {
      const [item, newI] = parseTokens(tokens, i);
      list.push(item);
      i = newI;
    }
    return [list, i + 1];
  }

  return [token, start + 1];
}

/**
 * Converts a formula AST to a LaTeX string.
 *The AST MUST be produced by parseFormula.
 * [👤compose📚js🗃️sketchpad💻quality🔖functions🛠️formulatolatex](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Quality.tsx/s/Functions/d/i/formulaToLatex)
 **/
export function formulaToLatex(ast: any): string {
  if (typeof ast === "string") {
    if (ast.startsWith("'") && ast.endsWith("'")) {
      const content = ast.slice(1, -1);
      if (/\d+\s*[a-zA-Z²³°]+/.test(content)) {
        return `\\text{${content}}`;
      }
      return `\\text{"${content}"}`;
    } else if (ast.startsWith("$")) {
      return `\\textit{${ast.substring(1)}}`;
    } else if (ast.includes(".")) {
      return `\\mathit{${ast}}`;
    } else if (!isNaN(Number(ast))) {
      return ast;
    } else {
      return `\\text{${ast}}`;
    }
  }

  if (Array.isArray(ast) && ast.length > 0) {
    const functionName = ast[0];
    const operands = ast.slice(1);

    const fn = formulaFunctions[functionName];
    if (fn) {
      const operandLatex = operands.map((op) => formulaToLatex(op));
      return fn.toLatex(...operandLatex);
    }

    const operandLatex = operands.map((op) => formulaToLatex(op));
    return `\\text{${functionName}}(${operandLatex.join(", ")})`;
  }

  return "\\text{?}";
}

// [👤compose📚js🗃️sketchpad💻quality🔖functions🛠️inversequalityappselectiondiff](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Quality.tsx/s/Functions/d/i/inverseQualityAppSelectionDiff)
/**
