          {quality.description && <p className="text-sm">{quality.description}</p>}
          {quality.formula && (
            <div className="text-xs text-muted-foreground mt-2">
              <span className="font-mono">{quality.formula}</span>
            </div>
          )}
        </div>
      </HoverCardContent>
    </HoverCard>
  );
};

