// [👤compose📚js🗃️sketchpad💻docstsx🔖mdxloader](composerepo://section/COMPOSE/JS/SKETCHPAD/DOCS.TSX/MDX-LOADER)
// MDX file loading and section discovery utilities MUST be declared here.

/**
 * MDX module with default component and optional frontmatter.
 * [👤compose📚js🗃️sketchpad💻docs🔖mdxloader🛠️mdxmodule](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Docs.tsx/s/MDX%20Loader/d/i/MDXModule)
 **/
export interface MDXModule {
  default: React.ComponentType;
  frontmatter?: PageFrontmatter;
}

/**
 * Frontmatter metadata for a docs section index page.
 * [👤compose📚js🗃️sketchpad💻docs🔖mdxloader🛠️sectionfrontmatter](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Docs.tsx/s/MDX%20Loader/d/i/SectionFrontmatter)
 **/
export interface SectionFrontmatter {
  title?: string;
  description?: string;
  icon?: string;
  order?: number;
  sidebar?: {
    label?: string;
  };
}

/**
 * File info for a loaded MDX file including path, section, and frontmatter.
 * [👤compose📚js🗃️sketchpad💻docs🔖mdxloader🛠️mdxfileinfo](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Docs.tsx/s/MDX%20Loader/d/i/MDXFileInfo)
 **/
export interface MDXFileInfo {
  path: string;
  section: string;
  title: string;
  description?: string;
  icon?: string;
  order?: number;
  concepts?: string[];
  module?: MDXModule;
}

/**
 * Metadata for a docs section including label, icon, and sort order.
 * [👤compose📚js🗃️sketchpad💻docs🔖mdxloader🛠️sectioninfo](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Docs.tsx/s/MDX%20Loader/d/i/SectionInfo)
 **/
export interface SectionInfo {
  id: string;
  label: string;
  description?: string;
  icon?: string;
  order: number;
}

/**
 * mdxModules holds the data fields for a mdxModules record.
 * [👤compose📚js🗃️sketchpad💻docs🔖mdxloader🪨mdxmodules](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Docs.tsx/s/MDX%20Loader/d/i/mdxModules)
 **/
const mdxModules = import.meta.glob<MDXModule>("./pages/**/*.mdx", { eager: true });

/**
 * Loads an MDX file by path from the eager-loaded module map.
 *The path MUST be relative to the pages directory without extension.
 * [👤compose📚js🗃️sketchpad💻docs🔖mdxloader🛠️loadmdxfile](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Docs.tsx/s/MDX%20Loader/d/i/loadMDXFile)
 **/
export async function loadMDXFile(path: string): Promise<MDXModule | null> {
  const cleanPath = path.replace(/^docs\//, "");
  const possibleKeys = Object.keys(mdxModules).filter((key) => {
    const keyPath = key.replace("./pages/", "").replace(".mdx", "");
    return keyPath === cleanPath || keyPath === `${cleanPath}/index`;
  });

  if (possibleKeys.length > 0) {
    const modulePath = possibleKeys[0];
    try {
      const module = mdxModules[modulePath];
      return module;
    } catch {
      return null;
    }
  }
  return null;
}

/** pathToSection holds the data fields for a pathToSection record.
 **/
// [👤compose📚js🗃️sketchpad💻docs🔖mdxloader🛠️pathtosection](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Docs.tsx/s/MDX%20Loader/d/i/pathToSection)
/**
 * [👤compose📚js🗃️sketchpad💻docs🔖mdxloader🪨pathtosection](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Docs.tsx/s/MDX%20Loader/d/i/pathToSection)
 **/
function pathToSection(filePath: string): string {
  const parts = filePath.replace("./pages/", "").split("/");
  return parts[0] || "root";
}

/** pathToTitle holds the data fields for a pathToTitle record.
 **/
// [👤compose📚js🗃️sketchpad💻docs🔖mdxloader🛠️pathtotitle](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Docs.tsx/s/MDX%20Loader/d/i/pathToTitle)
/**
 * [👤compose📚js🗃️sketchpad💻docs🔖mdxloader🪨pathtotitle](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Docs.tsx/s/MDX%20Loader/d/i/pathToTitle)
 **/
function pathToTitle(filePath: string, frontmatter?: PageFrontmatter): string {
  if (frontmatter?.title) return frontmatter.title;
  const parts = filePath.replace("./pages/", "").replace(".mdx", "").split("/");
  const fileName = parts[parts.length - 1];
  if (fileName === "index") return parts[parts.length - 2] || "Home";
  return fileName
    .split("-")
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(" ");
}

/**
 * Returns all MDX files with resolved frontmatter and section info.
 *Index files for sections MUST be excluded from the flat list.
 * [👤compose📚js🗃️sketchpad💻docs🔖mdxloader🛠️getallmdxfiles](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Docs.tsx/s/MDX%20Loader/d/i/getAllMDXFiles)
 **/
export function getAllMDXFiles(): MDXFileInfo[] {
  return Object.keys(mdxModules)
    .filter((filePath) => {
      const parts = filePath.replace("./pages/", "").split("/");
      if (filePath === "./pages/index.mdx") return true;
      if (parts.length === 2 && parts[1] === "index.mdx") return false;
      return true;
    })
    .map((filePath) => {
      const module = mdxModules[filePath];
      const cleanPath = filePath.replace("./pages/", "").replace(".mdx", "");
      const fullPath = `docs/${cleanPath}`;
      const frontmatter = module.frontmatter;
      return {
        path: fullPath,
        section: pathToSection(filePath),
        title: pathToTitle(filePath, frontmatter),
        description: frontmatter?.description,
        icon: frontmatter?.icon,
        order: frontmatter?.order ?? 999,
        concepts: frontmatter?.concepts,
        module,
      };
    });
}

/**
 * Returns MDX files filtered by section and sorted by order.
 *The section parameter MUST match a top-level page directory.
 * [👤compose📚js🗃️sketchpad💻docs🔖mdxloader🛠️getmdxfilesbysection](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Docs.tsx/s/MDX%20Loader/d/i/getMDXFilesBySection)
 **/
export function getMDXFilesBySection(section: string): MDXFileInfo[] {
  return getAllMDXFiles()
    .filter((file) => file.section === section)
    .sort((a, b) => (a.order ?? 999) - (b.order ?? 999));
}

/**
 * Returns all docs sections discovered from the MDX file structure.
 *Sections MUST be sorted by their order field.
 * [👤compose📚js🗃️sketchpad💻docs🔖mdxloader🛠️getallsections](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Docs.tsx/s/MDX%20Loader/d/i/getAllSections)
 **/
export function getAllSections(): SectionInfo[] {
  const sectionsMap = new Map<string, SectionInfo>();
  Object.keys(mdxModules).forEach((filePath) => {
    const parts = filePath.replace("./pages/", "").split("/");
    if (parts.length > 1) {
      const sectionId = parts[0];
      if (!sectionsMap.has(sectionId)) {
        const indexPath = `./pages/${sectionId}/index.mdx`;
        const indexModule = mdxModules[indexPath];
        const frontmatter = indexModule?.frontmatter as SectionFrontmatter | undefined;
        sectionsMap.set(sectionId, {
          id: sectionId,
          label:
            frontmatter?.sidebar?.label ||
            frontmatter?.title ||
            sectionId
              .split("-")
              .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
              .join(" "),
          description: frontmatter?.description,
          icon: frontmatter?.icon,
          order: frontmatter?.order ?? 999,
        });
      }
    }
  });
  return Array.from(sectionsMap.values()).sort((a, b) => a.order - b.order);
}

