// #region Commands

// [👤compose📚js🗃️sketchpad💻docstsx🔖commands](composerepo://section/COMPOSE/JS/SKETCHPAD/DOCS.TSX/COMMANDS)
// Docs app command handlers MUST modify state through diff objects.

/**
 * Command handlers for docs app page selection, section toggling, and progress tracking.
 * [👤compose📚js🗃️sketchpad💻docs🔖commands🪨docscommands](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Docs.tsx/s/Commands/d/i/docsCommands)
 **/
export const docsCommands = {
  "compose.docsApp.selectPage": async (context: DocsCommandContext, section: string, page: string): Promise<DocsCommandResult> => {
    return {
      diff: {
        selection: {
          section: { prev: context.docs.selection?.section, next: section },
          page: { prev: context.docs.selection?.page, next: page },
        },
      },
    };
  },
  "compose.docsApp.toggleSection": async (context: DocsCommandContext, section: string): Promise<DocsCommandResult> => {
    const currentState = context.docs.sectionStates?.[section] || { isExpanded: false };
    return {
      diff: {
        sectionStatesDiff: {
          [section]: { isExpanded: !currentState.isExpanded },
        },
      },
    };
  },
  "compose.docsApp.updateSectionProgress": async (context: DocsCommandContext, section: string, progress: number): Promise<DocsCommandResult> => {
    return {
      diff: {
        sectionStatesDiff: {
          [section]: { progress },
        },
      },
    };
  },
  "compose.docsApp.markPageComplete": async (context: DocsCommandContext, section: string, page: string): Promise<DocsCommandResult> => {
    const currentState = context.docs.sectionStates?.[section] || { isExpanded: false, completedPages: [] };
    const completedPages = currentState.completedPages || [];
    if (!completedPages.includes(page)) {
      completedPages.push(page);
    }
    return {
      diff: {
        sectionStatesDiff: {
          [section]: { completedPages: [...completedPages] },
        },
      },
    };
  },
};

if (typeof window !== "undefined") {
  registerDocsAppStoreFactory((parent) => {
    const store = new DocsAppStore(parent);
    Object.entries(docsCommands).forEach(([commandId, command]) => {
      store.registerCommand(commandId, command as any);
    });
    return store;
  });
}

