// #region App

// [👤compose📚js🗃️sketchpad💻docstsx🔖app](composerepo://section/COMPOSE/JS/SKETCHPAD/DOCS.TSX/APP)
// Docs app root component MUST compose MDX routing, panel sections, and layout.

/**
 * Window kind identifiers for docs app layout.
 * [👤compose📚js🗃️sketchpad💻docs🔖app🛠️app](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Docs.tsx/s/App/d/i/App)
 **/
export enum DocsAppWindowKind {
  Page = "page",
}

// [👤compose📚js🗃️sketchpad💻docs🔖app🪨app](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Docs.tsx/s/App/d/i/App)
/**
 * [👤compose📚js🗃️sketchpad💻docs🔖app🪨app](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Docs.tsx/s/App/d/i/App)
 * App holds the data fields for a App record.
 **/
const App: FC = () => {
  const { "*": routePath } = useParams();
  const location = useLocation();
  const appType = useAppType();
  const addSection = useAddPanelSection();
  const addSidePanelTab = useAddSidePanelTab();
  const removeSection = useRemovePanelSection();
  const removeSidePanelTab = useRemoveSidePanelTab();
  useFocus();
  const settings = useSettings();
  const sketchpadCommands = useSketchpadCommands();
  const [mdxModule, setMdxModule] = useState<MDXModule | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const docsPath = useMemo(() => {
    const raw = (routePath ?? "").trim();
    if (raw) return raw;
    const fromLocation = location.pathname.replace(/^\//, "").replace(/^docs\/?/, "");
    return fromLocation.trim() || "index";
  }, [routePath, location.pathname]);

  useEffect(() => {
    if (appType !== "docs") return;
    addSidePanelTab("right", {
      id: "compose.sketchpad.app.docs.settings",
      icon: SettingsIcon,
      order: 100,
      content: () => (
        <TreeStateProvider>
          <Tree className="min-w-0 overflow-hidden p-double" sections={[{ id: "compose.sketchpad.app.docs.settings.content", label: null, content: <Settings /> }]} />
        </TreeStateProvider>
      ),
    });
    addSidePanelTab("right", {
      id: "compose.sketchpad.app.docs.chat",
      icon: ChatIcon,
      order: 101,
      content: () => <BasicChatPanel id="compose.sketchpad.app.docs.chat" title="Docs" />,
    });
    return () => {
      removeSidePanelTab("right", "compose.sketchpad.app.docs.settings");
      removeSidePanelTab("right", "compose.sketchpad.app.docs.chat");
    };
  }, [appType, addSidePanelTab, removeSidePanelTab]);

  const defaultLayout = useMemo(
    () => ({
      root: {
        type: "row",
        content: [
          {
            type: "stack",
            size: "100%",
            content: [
              {
                type: "component",
                componentName: DocsAppWindowKind.Page,
                title: "page",
                componentState: {},
              },
            ],
          },
        ],
      },
    }),
    [],
  );
  const storedWindowLayout = useMemo(() => parseWindowLayout(settings?.apps?.docs?.windowLayout), [settings]);
  const windowLayout = useMemo(() => {
    if (!storedWindowLayout) return defaultLayout;
    const removeWorkbenchWindowFromLayout = (layoutNode: any): any => {
      if (!layoutNode || typeof layoutNode !== "object") return layoutNode;
      if (layoutNode.type === "component" && (layoutNode.componentName === "workbench" || layoutNode.componentName === "settings" || layoutNode.componentName === "chat")) {
        return null;
      }
      if (layoutNode.root && typeof layoutNode.root === "object") {
        const root = removeWorkbenchWindowFromLayout(layoutNode.root);
        if (!root) return undefined;
        return { ...layoutNode, root };
      }
      if (Array.isArray(layoutNode.content)) {
        const content = layoutNode.content.map((item: any) => removeWorkbenchWindowFromLayout(item)).filter(Boolean);
        if (content.length === 0 && (layoutNode.type === "stack" || layoutNode.type === "row" || layoutNode.type === "column")) return null;
        return { ...layoutNode, content };
      }
      if (Array.isArray(layoutNode.contentItems)) {
        const contentItems = layoutNode.contentItems.map((item: any) => removeWorkbenchWindowFromLayout(item)).filter(Boolean);
        if (contentItems.length === 0 && (layoutNode.type === "stack" || layoutNode.type === "row" || layoutNode.type === "column")) return null;
        return { ...layoutNode, contentItems };
      }
      return layoutNode;
    };
    return removeWorkbenchWindowFromLayout(storedWindowLayout) || defaultLayout;
  }, [storedWindowLayout, defaultLayout]);
  const lastLayoutRef = useRef<any>(null);

  useEffect(() => {
    if (appType !== "docs") return;
    addSection("workbench", {
      id: "compose.sketchpad.app.docs.docs",
      specificity: 20,
      order: 1,
      content: () => <Workbench />,
    });
    addSection("workbench", {
      id: "compose.sketchpad.app.docs.overview",
      specificity: 20,
      order: 2,
      content: () => <Overview />,
    });
    addSection("details", {
      id: "compose.sketchpad.app.docs.page",
      specificity: 20,
      order: 1,
      content: () => <Details />,
    });

    addSection("toolbar", {
      id: "compose.sketchpad.app.docs.toolbar.empty",
      specificity: 20,
      order: 0,
      toolbarPlaceholder: true,
      content: () => null,
    });

    return () => {
      removeSection("workbench", "compose.sketchpad.app.docs.docs");
      removeSection("workbench", "compose.sketchpad.app.docs.overview");
      removeSection("details", "compose.sketchpad.app.docs.page");
      removeSection("toolbar", "compose.sketchpad.app.docs.toolbar.empty");
    };
  }, [appType, addSection, removeSection]);

  useEffect(() => {
    if (appType !== "docs") {
      setLoading(false);
      return;
    }

    const loadContent = async () => {
      setLoading(true);
      setError(null);
      try {
        const module = await loadMDXFile(docsPath);
        if (module) {
          setMdxModule(module);
        } else {
          setError(`Failed to load ${docsPath}`);
        }
      } catch (err) {
        setError((err as Error).message);
      } finally {
        setLoading(false);
      }
    };

    loadContent();
  }, [docsPath, appType]);

  const windowConfig: AppWindowConfig = useMemo(
    () => ({
      windowKinds: [
        {
          id: DocsAppWindowKind.Page,
          label: "page",
          component: () => {
            if (loading) return <PageCanvas frontmatter={{ title: "Loading...", description: "" }} />;
            if (error || !mdxModule) return <PageCanvas frontmatter={{ title: "Error", description: error || "Content not found" }} />;
            return <PageCanvas MDXContent={mdxModule.default} frontmatter={mdxModule.frontmatter} />;
          },
        },
      ],
      defaultLayout,
    }),
    [defaultLayout, error, loading, mdxModule],
  );

  const handleLayoutChange = useCallback(
    (layout: any) => {
      const next = stringifyWindowLayout(layout);
      if (!next) return;
      const prev = stringifyWindowLayout(lastLayoutRef.current);
      if (next === prev) return;
      lastLayoutRef.current = layout;
      sketchpadCommands.setState("compose.sketchpad.app.docs.windowLayout", {
        settings: {
          apps: {
            docs: {
              windowLayout: next,
            },
          },
        },
      });
    },
    [sketchpadCommands],
  );

  return (
    <HeadingsProvider>
      <Canvas>
        <LayoutCanvas windowConfig={windowConfig} layoutState={windowLayout} onLayoutChange={handleLayoutChange} />
      </Canvas>
    </HeadingsProvider>
  );
};

export default App;

