  async executeCommand<T>(command: string, ...args: any[]): Promise<T> {
    let origin: string | undefined;
    let rest: any[];

    if (typeof args[0] === "string" && args[0].startsWith("compose.sketchpad.")) {
      origin = args[0];
      rest = args.slice(1);
    } else {
      origin = undefined;
      rest = args;
    }

    if (command === "compose.kitApp.startTransaction") {
      this.startTransaction();
      return {} as T;
    }
    if (command === "compose.kitApp.finalizeTransaction") {
      this.finalizeTransaction();
      return {} as T;
    }
    if (command === "compose.kitApp.abortTransaction") {
      this.abortTransaction();
      return {} as T;
    }
    if (command === "compose.kitApp.undo") {
      this.undo();
      return {} as T;
    }
    if (command === "compose.kitApp.redo") {
      this.redo();
      return {} as T;
    }

    const callback = this.commandRegistry.get(command);
    if (!callback) throw new Error(`Command "${command}" not found in kit app controller`);

    const kitData = this.kit();
    const state = this.snapshot();

    const context: KitAppCommandContext = {
      kitApp: state,
      kit: kitData.snapshot(),
      fileUrls: kitData.fileUrls,
      origin,
    };
    const result = callback(context, ...rest);
    if (result.diff) {
      this.change(result.diff);
    }
    this.recordEdit(result);
    if (result.kitDiff) {
      kitData.change(result.kitDiff);
    }
    return result as T;
  }

  execute<T>(command: string, ...rest: any[]): Promise<T> {
    return this.executeCommand(command, ...rest);
  }
