 * ArtifactKind holds the data fields for a ArtifactKind record.
 **/
type ArtifactKind = "designs" | "types" | "qualities" | "ports" | "tags" | "concepts" | "files" | "folders" | "authors";

// [👤compose📚js🗃️sketchpad💻kit🔖internalstatemanagement🔖canvas🔖windows🔖table🪨kitkindtoggles](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Kit.tsx/s/Internal%20State%20Management/s/Canvas/s/Windows/s/Table/d/i/KitKindToggles)
/**
 * [👤compose📚js🗃️sketchpad💻kit🔖internalstatemanagement🔖canvas🔖windows🔖table🪨kitkindtoggles](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Kit.tsx/s/Internal%20State%20Management/s/Canvas/s/Windows/s/Table/d/i/KitKindToggles)
 * KitKindToggles holds the data fields for a KitKindToggles record.
 **/
const KitKindToggles: FC = () => {
  const [searchParams, setSearchParams] = useSearchParams();

  const selectedKindsFromUrl = useMemo(() => searchParams.getAll("kind") as ArtifactKind[], [searchParams]);
  const selectedKinds = useMemo(() => new Set(selectedKindsFromUrl), [selectedKindsFromUrl]);

  const toggleKind = (kind: ArtifactKind) => {
    const newParams = new URLSearchParams(searchParams);
    const kinds = newParams.getAll("kind") as ArtifactKind[];

    if (kinds.length === 0) {
      newParams.append("kind", kind);
    } else if (kinds.includes(kind)) {
      const remaining = kinds.filter((k) => k !== kind);
      newParams.delete("kind");
      remaining.forEach((k) => newParams.append("kind", k));
    } else {
      newParams.append("kind", kind);
    }

    newParams.delete("name");
    newParams.delete("variant");
    newParams.delete("view");
    setSearchParams(newParams);
  };

  const labelDesigns = useLabel("compose.sketchpad.app.kit.toolbar.showDesigns");
  const labelTypes = useLabel("compose.sketchpad.app.kit.toolbar.showTypes");
  const labelQualities = useLabel("compose.sketchpad.app.kit.toolbar.showQualities");
  const labelPorts = useLabel("compose.sketchpad.app.kit.toolbar.showPorts");
  const labelTags = useLabel("compose.sketchpad.app.kit.toolbar.showTags");
  const labelConcepts = useLabel("compose.sketchpad.app.kit.toolbar.showConcepts");
  const labelFiles = useLabel("compose.sketchpad.app.kit.toolbar.showFiles");
  const labelFolders = useLabel("compose.sketchpad.app.kit.toolbar.showFolders");
  const labelAuthors = useLabel("compose.sketchpad.app.kit.toolbar.showAuthors");

  return (
    <ToolbarGroup>
      <Toggle pressed={selectedKinds.has("designs")} onPressedChange={() => toggleKind("designs")} id="compose.sketchpad.app.kit.toolbar.showDesigns" icon={<LayoutIcon />} text={labelDesigns} />
      <Toggle pressed={selectedKinds.has("types")} onPressedChange={() => toggleKind("types")} id="compose.sketchpad.app.kit.toolbar.showTypes" icon={<TypeIcon />} text={labelTypes} />
      <Toggle pressed={selectedKinds.has("qualities")} onPressedChange={() => toggleKind("qualities")} id="compose.sketchpad.app.kit.toolbar.showQualities" icon={<AwardIcon />} text={labelQualities} />
      <Toggle pressed={selectedKinds.has("ports")} onPressedChange={() => toggleKind("ports")} id="compose.sketchpad.app.kit.toolbar.showPorts" icon={<PortIcon />} text={labelPorts} />
      <Toggle pressed={selectedKinds.has("tags")} onPressedChange={() => toggleKind("tags")} id="compose.sketchpad.app.kit.toolbar.showTags" icon={<HashIcon />} text={labelTags} />
      <Toggle pressed={selectedKinds.has("concepts")} onPressedChange={() => toggleKind("concepts")} id="compose.sketchpad.app.kit.toolbar.showConcepts" icon={<LightbulbIcon />} text={labelConcepts} />
      <Toggle pressed={selectedKinds.has("files")} onPressedChange={() => toggleKind("files")} id="compose.sketchpad.app.kit.toolbar.showFiles" icon={<DocumentIcon />} text={labelFiles} />
      <Toggle pressed={selectedKinds.has("folders")} onPressedChange={() => toggleKind("folders")} id="compose.sketchpad.app.kit.toolbar.showFolders" icon={<FolderIcon />} text={labelFolders} />
      <Toggle pressed={selectedKinds.has("authors")} onPressedChange={() => toggleKind("authors")} id="compose.sketchpad.app.kit.toolbar.showAuthors" icon={<UserIcon />} text={labelAuthors} />
    </ToolbarGroup>
  );
};

