/**
 * [👤compose📚js🗃️sketchpad💻kit🔖internalstatemanagement🔖canvas🔖windows🔖table🪨kitcreateactions](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Kit.tsx/s/Internal%20State%20Management/s/Canvas/s/Windows/s/Table/d/i/KitCreateActions)
 **/
const KitCreateActions: FC = () => {
  const [searchParams, setSearchParams] = useSearchParams();
  const kit = useKit() as Kit | undefined;
  const kitCommands = useKitCommands();
  const sketchpadCommands = useSketchpadCommands();

  const defaultDesignName = useLabel("compose.sketchpad.app.kit.defaultDesignName");
  const defaultTypeName = useLabel("compose.sketchpad.app.kit.defaultTypeName");
  const defaultQualityName = useLabel("compose.sketchpad.app.quality.defaultName");
  const defaultPortName = useLabel("compose.sketchpad.app.port.defaultName");
  const defaultTagName = useLabel("compose.sketchpad.app.tag.defaultName");
  const defaultConceptName = useLabel("compose.sketchpad.app.concept.defaultName");
  const defaultFolderName = useLabel("compose.sketchpad.app.folder.defaultName");

  const setKindActive = (kind: ArtifactKind) => {
    const newParams = new URLSearchParams(searchParams);
    newParams.delete("kind");
    newParams.append("kind", kind);
    newParams.delete("name");
    newParams.delete("variant");
    newParams.delete("view");
    setSearchParams(newParams);
  };

  const handleCreateArtifact = (kind: ArtifactKind) => {
    if (!kit || !kitCommands) return;
