/**
 * Detail section component for the selected file.
 *MUST render the file metadata within a detail panel section.
 * [👤compose📚js🗃️sketchpad💻kit🔖designfamilyhelpers🔖internalstatemanagement🔖canvas🔖windows🔖panels🔖right🔖details🪨filesection](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Kit.tsx/s/Design%20Family%20Helpers/s/Internal%20State%20Management/s/Canvas/s/Windows/s/Panels/s/Right/s/Details/d/i/FileSection)
 **/
export const FileSection: FC = () => {
  const { t } = useTranslation();
  const kit = useKit() as Kit;
  const [selection] = useKitAppSelection();
  const selectedFiles = selection?.files || [];

  if (selectedFiles.length === 0) return null;

  const files = selectedFiles
    .map((fileGuid) => {
      return kit.files?.find((f) => f.guid === fileGuid);
    })
    .filter(Boolean);

  if (files.length === 0) return null;

  const formatFileSize = (bytes?: number) => {
    if (!bytes) return "0 KB";
    return `${(bytes / 1024).toFixed(1)} KB`;
  };

  const formatDate = (date?: Date | string) => {
    if (!date) return "";
    const parsedDate = date instanceof Date ? date : new Date(date);
    if (isNaN(parsedDate.getTime())) return "";
    return parsedDate.toLocaleDateString();
  };

  return (
    <>
      {files.map((file) => (
        <TreeRow key={file!.guid}>
          <div className="space-y-2">
            <div>
              <label className="text-xs text-muted-foreground">{useLabel("compose.file.name")}</label>
              <p className="text-sm">{file!.name}</p>
            </div>
            <div>
              <label className="text-xs text-muted-foreground">{useLabel("compose.file.size")}</label>
              <p className="text-sm">{formatFileSize(file!.size)}</p>
            </div>
            {file!.createdAt && (
              <div>
                <label className="text-xs text-muted-foreground">{useLabel("compose.file.created")}</label>
                <p className="text-sm">{formatDate(file!.createdAt)}</p>
              </div>
            )}
            {file!.updatedAt && (
              <div>
                <label className="text-xs text-muted-foreground">{useLabel("compose.file.updated")}</label>
                <p className="text-sm">{formatDate(file!.updatedAt)}</p>
              </div>
            )}
          </div>
        </TreeRow>
      ))}
    </>
  );
};

