      return { designApps: { ...context.designApps, [key]: { ...app, selection: { ...app.selection, connections } } } };
    },
  });
  registerEventHandler("DESIGN.DESELECT_CONNECTION", {
    action: (context: any, event: any) => {
      const key = `${event.kitGuid}:${event.designGuid}`;
