/** useDesignAppInitialize holds the data fields for a useDesignAppInitialize record.
 **/
// [👤compose📚js🗃️sketchpad💻design🔖imports🔖store🔖hooks🛠️usedesignappinitialize](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Design.tsx/s/Imports/s/Store/s/Hooks/d/i/useDesignAppInitialize)
/**
 * [👤compose📚js🗃️sketchpad💻design🔖store🔖hooks🪨usedesignappinitialize](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Design.tsx/s/Store/s/Hooks/d/i/useDesignAppInitialize)
 **/
function useDesignAppInitialize() {
  const actor = useSketchpadActor();
  const kitScope = useKitScope();
  const designScope = useDesignScope();
  const kitGuid = kitScope?.guid ?? "";
  const designGuid = designScope?.guid ?? "";
  const initializedKeyRef = useRef<string | null>(null);

  useLayoutEffect(() => {
    if (!kitGuid || !designGuid) return;
    const initKey = `${kitGuid}:${designGuid}`;
    if (initializedKeyRef.current === initKey) return;
    actor.send({
      type: "DESIGN.INIT",
      kitGuid,
      designGuid,
      state: {
        panelVisibility: { toolbar: true, leftSidePanel: true, rightSidePanel: true, details: true },
        selection: undefined,
        hover: undefined,
        camera: undefined,
        fullscreenWindow: DesignAppFullscreenWindow.None,
        selectedModelTags: {},
        transaction: {
          isTransactionActive: false,
          currentTransactionStack: [],
          pastTransactionStack: [],
          redoStack: [],
        },
      },
    });
    initializedKeyRef.current = initKey;
  }, [actor, kitGuid, designGuid]);
}

