  if (a.length !== b.length) return false;
  for (let index = 0; index < a.length; index++) {
    if (a[index]?.piece !== b[index]?.piece || a[index]?.designPiece !== b[index]?.designPiece || a[index]?.connector !== b[index]?.connector) return false;
