    () => (selection.pieces || []).map((entry) => resolveSelectionEntryGuidByKnownIds(entry, knownSelectablePieceIds)).filter((entry): entry is Guid => typeof entry === "string" && entry.length > 0),
    [selection.pieces, knownSelectablePieceIds],
  );
