/** getConnectorPositionStyle holds the data fields for a getConnectorPositionStyle record.
 **/
// [👤compose📚js🗃️sketchpad💻design🔖imports🔖panels🔖canvas🔖diagram🪨getconnectorpositionstyle](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Design.tsx/s/Imports/s/Panels/s/Canvas/s/Diagram/d/i/getConnectorPositionStyle)
/**
 * [👤compose📚js🗃️sketchpad💻design🔖canvas🔖diagram🪨getconnectorpositionstyle](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Design.tsx/s/Canvas/s/Diagram/d/i/getConnectorPositionStyle)
 **/
const getConnectorPositionStyle = (connector: Connector): { x: number; y: number } => {
  const { t } = connector;
  if (t === undefined) {
    return { x: 0, y: 0 };
  }
  const angle = t * 2 * Math.PI;
  const radius = ICON_WIDTH / 2;
  return {
    x: radius * Math.sin(angle),
    y: -(radius * Math.cos(angle) - radius),
  };
};

// [👤compose📚js🗃️sketchpad💻design🔖canvas🔖diagram🪨connectorhandle](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Design.tsx/s/Canvas/s/Diagram/d/i/ConnectorHandle)
/**
 * [👤compose📚js🗃️sketchpad💻design🔖canvas🔖diagram🪨connectorhandle](repo://p/u/compose/b/l/js/fd/org/sketchpad/f/Design.tsx/s/Canvas/s/Diagram/d/i/ConnectorHandle)
 * ConnectorHandle holds the data fields for a ConnectorHandle record.
 **/
const ConnectorHandle: React.FC<ConnectorHandleProps> = ({ connector, pieceId, selected = false, onPortClick }) => {
  const { x, y } = getConnectorPositionStyle(connector);
  const kit = useKit() as Kit | undefined;
  const selectedPortGuid = useContext(SelectedConnectorPortContext);
  const connectorPortGuid = getConnectorPortGuid(connector);
  const tone = getPortTone(connectorPortGuid, kit?.ports ?? []);
  const compatibilityState = getPortCompatibilityState(connectorPortGuid, selectedPortGuid, kit?.ports ?? []);
  const [hoverPort] = useDesignAppHoverPort();

  const isHovered = useDesignAppIsPortHovered(undefined, pieceId, connector.guid ?? "");

  const onClick = (event: React.MouseEvent) => {
    event.stopPropagation();
    onPortClick(connector);
  };

  return (
    <Handle
      id={connector.guid ?? ""}
      type="source"
      className="left-1/2 top-0 cursor-selectable"
      style={{
        left: x + ICON_WIDTH / 2,
        top: y,
        backgroundColor: selected ? "var(--active-base)" : isHovered ? "var(--hover-base)" : compatibilityState === "compatible" ? tone.surfaceStrong : compatibilityState === "incompatible" ? "hsla(0 72% 52% / 0.32)" : tone.base,
        border: selected || isHovered ? "2px solid var(--border-element-color)" : compatibilityState === "compatible" ? "1px solid hsl(141 57% 40%)" : compatibilityState === "incompatible" ? "1px solid hsl(0 74% 44%)" : `1px solid ${tone.border}`,
        zIndex: selected || isHovered ? 20 : 10,
      }}
      position={Position.Top}
      role="button"
      onClick={onClick}
      onPointerEnter={() => {
        if (connector.guid && hoverPort) hoverPort(pieceId, connector.guid);
      }}
      onPointerLeave={() => {}}
    />
  );
};

