          >
            {renderTypeTree(rootTypes)}
          </TreeItem>
        </div>
        <div
          onPointerEnter={() => {
            if (!workbenchDesigns || workbenchDesigns.length === 0) return;
            if (hoverDesigns) hoverDesigns(workbenchDesigns.map((design) => design.guid));
