type SyncDesignVal = string | boolean | number | SyncAuthorUuids | SyncAttributes | SyncPieces | SyncConnections | SyncLayers | SyncGroups | SyncStats | SyncProps | SyncLocation | SyncArray<string>;
// [👤compose📚js🗃️sketchpad💻sketchpad🔖utilities🔖store🔖design✂️ydesign](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Store/s/Design/d/i/SyncDesign)
