/**
 * Hook returning all folders of the targeted kit.
 * [👤compose📚js🗃️sketchpad💻sketchpad🔖kit🔖targetedkithooks🛠️usekitfolders](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Kit/s/Targeted%20Kit%20Hooks/d/i/useKitFolders)
 **/
export function useKitFolders(guid?: Guid): Folder[] {
  const kitScope = useKitScope();
  const resolvedGuid = guid ?? kitScope?.guid;
  const kitStore = useKitStore(identitySelector, resolvedGuid) as CollaborativeKitStore | null;

  const subscribe = useCallback(
    (callback: () => void) => {
      if (!kitStore) return () => {};
      return kitStore.onFoldersChanged((cb: () => void) => {
        cb();
        callback();
        return () => {};
      }, true);
    },
    [kitStore],
  );

  const getSnapshot = useCallback(() => {
    if (!kitStore) return EMPTY_FOLDERS;
    return kitStore.snapshotFolders();
  }, [kitStore]);

  return useSyncExternalStore(subscribe, getSnapshot);
}

