/**
 * Hook returning shallow kit data for all kits with reactive updates.
 * [👤compose📚js🗃️sketchpad💻sketchpad🔖apps🔖sketchpad🛠️usekitshallows](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Apps/s/Sketchpad/d/i/useKitShallows)
 **/
export function useKitShallows(): KitShallow[] {
  const store = useSketchpadStore();
  return useSyncExternalStore(
    (onStoreChange) => {
      const unsubscribeCreated = store.onKitCreated(onStoreChange);
      const unsubscribeDeleted = store.onKitDeleted(onStoreChange);
      const unsubscribers = store.kitShallows().map((kitShallow) => {
        const kitStore = store.kit(kitShallow.guid);
        return kitStore.onChanged((cb: () => void) => {
          cb();
          onStoreChange();
          return () => {};
        });
      });
      return () => {
        unsubscribeCreated();
        unsubscribeDeleted();
        unsubscribers.forEach((unsub) => unsub());
      };
    },
    () => store.kitShallows(),
  );
}

