 * [👤compose📚js🗃️sketchpad💻sketchpad🔖apps🔖sketchpad🛠️usesketchpadcommands](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Apps/s/Sketchpad/d/i/useSketchpadCommands)
 **/
export function useNavigate() {
  const store = useSketchpadStore();
  const reactNavigate = useReactNavigate();
  return useCallback(
    (to: string | number, options?: { replace?: boolean; state?: any }) => {
      if (!reactNavigate) return;
      if (typeof to === "number") {
        reactNavigate(to);
      }
      const fullPath = to + (options?.state?.search || "");
      store.execute("compose.sketchpad.addNavigation", "compose.sketchpad.navigation", fullPath);
      reactNavigate(to, options);
    },
    [store, reactNavigate],
  );
}

