      } else {
        breadcrumbItems[existingNameIndex] = {
          ...breadcrumbItems[existingNameIndex],
          options: kitVersionItems,
          onNavigate: (href) => {
            if (href === "#create-version") handleCreateVersion("compose.sketchpad.navbar.versions");
            else navigate(href);
          },
        };
