/**
 * [👤compose📚js🗃️sketchpad💻sketchpad🔖store🔖canvas🪨windowcontrolsgroup](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Store/s/Canvas/d/i/WindowControlsGroup)
 * WindowControlsGroup holds the data fields for a WindowControlsGroup record.
 **/
const WindowControlsGroup: FC<{ controls: WindowControl[] }> = ({ controls }) => {
  if (!controls || controls.length === 0) return null;

  return (
    <div className="flex items-stretch border overflow-hidden h-large">
      {controls.map((control) => {
        if (control.kind === "toggle") {
          return (
            <Toggle
              key={control.id}
              id={control.id}
              pressed={control.value === "true" || control.value === "1"}
              onPressedChange={(pressed) => {
                if (control.onChange) {
                  control.onChange(pressed ? "true" : "false");
                }
              }}
              icon={control.icon}
            />
          );
        } else if (control.kind === "dropdown" && control.options) {
          return (
            <Toggle
              key={control.id}
              kind="dropdown"
              id={control.id}
              value={control.value || control.options[0]?.value}
              onValueChange={(value) => {
                if (control.onChange) {
                  control.onChange(value);
                }
              }}
              items={control.options.map((opt) => ({
                value: opt.value,
                label: opt.icon,
                id: `${control.id}.${opt.value}`,
              }))}
              pressed={!!control.value}
            >
              {control.icon}
            </Toggle>
          );
        }
        return null;
      })}
    </div>
  );
};

