// [👤compose📚js🗃️sketchpad💻sketchpad🔖sketchpadcomponents](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Sketchpad%20Components)
// Top-level sketchpad React components for rendering the complete application.

// [👤compose📚js🗃️sketchpad💻sketchpad🔖utilities🔖store🔖sketchpadcomponents🪨toolbarscopewrapper](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Store/s/Sketchpad%20Components/d/i/ToolbarScopeWrapper)
/**
 * [👤compose📚js🗃️sketchpad💻sketchpad🔖store🔖sketchpadcomponents🪨toolbarscopewrapper](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Store/s/Sketchpad%20Components/d/i/ToolbarScopeWrapper)
 * ToolbarScopeWrapper holds the data fields for a ToolbarScopeWrapper record.
 **/
const ToolbarScopeWrapper: FC<{ children: ReactNode }> = ({ children }) => {
  const location = useLocation();
  const scopeGuids = useMemo(() => {
    const pathMatch = location.pathname.match(/^\/kits\/([^/?]+)(?:\/(designs|types|qualities)\/([^/?]+))?/);
    return {
      kit: pathMatch?.[1],
      itemType: pathMatch?.[2],
      item: pathMatch?.[3],
    };
  }, [location.pathname]);

  const { kit, itemType, item } = scopeGuids;
  let wrapped = <>{children}</>;

  if (item && kit) {
    if (itemType === "qualities") {
      wrapped = <QualityScopeProvider guid={item}>{wrapped}</QualityScopeProvider>;
    } else if (itemType === "types") {
      wrapped = <TypeScopeProvider guid={item}>{wrapped}</TypeScopeProvider>;
    } else if (itemType === "designs") {
      wrapped = <DesignScopeProvider guid={item}>{wrapped}</DesignScopeProvider>;
    }
  }
  if (kit) {
    wrapped = <KitScopeProvider guid={kit}>{wrapped}</KitScopeProvider>;
  }

  return wrapped;
};

const PanelTabContent: FC<{ sections: PanelSection[] }> = ({ sections }) => {
  const sortedSections = [...sections].sort((a, b) => (a.order || 0) - (b.order || 0));
  const treeSections = sortedSections.map((section, index) => ({
    id: section.id,
    defaultOpen: section.defaultOpen ?? index === 0,
    actions: section.actions,
    onPointerEnter: section.onPointerEnter,
    onPointerLeave: section.onPointerLeave,
    onDoubleClick: section.onDoubleClick,
    content: typeof section.content === "function" ? section.content() : section.content,
  }));

  return (
    <TreeStateProvider>
      <Tree className="min-w-0 overflow-hidden" sections={treeSections} />
    </TreeStateProvider>
  );
};

const DynamicPanelTabContent: FC<{ panelKey: PanelKey }> = ({ panelKey }) => {
  const sections = usePanelSections(panelKey);
  return <PanelTabContent sections={sections} />;
};

const UtilityFallbackSettingsContent: FC<{ appType: string }> = ({ appType }) => {
  const appCommands = useAppCommands();
  const panelVisibility = useAppPanelVisibility();
  const showToolbarLabel = useLabel("compose.sketchpad.navbar.panelToggle.toolbar.show");
  const showWorkbenchLabel = useLabel("compose.sketchpad.navbar.panelToggle.workbench.show");
  const showDetailsLabel = useLabel("compose.sketchpad.navbar.panelToggle.details.show");
  const showWindowsLabel = useLabel("compose.sketchpad.navbar.panelToggle.tools.show");
  const togglePanelVisibility = useCallback(
    (panelKey: "toolbar" | "leftSidePanel" | "rightSidePanel" | "details") => {
      appCommands?.togglePanel?.(`compose.sketchpad.app.${appType}.settings.panel.${panelKey}`, panelKey);
    },
    [appCommands, appType],
  );
  return (
    <TreeStateProvider>
      <Tree
        className="min-w-0 overflow-hidden p-double"
        sections={[
          {
            id: `compose.sketchpad.app.${appType}.settings.panel`,
            label: null,
            content: (
              <>
                <Toggle id={`compose.sketchpad.app.${appType}.settings.panel.toolbar`} pressed={!!panelVisibility.toolbar} onPressedChange={() => togglePanelVisibility("toolbar")} text={showToolbarLabel} />
                <Toggle id={`compose.sketchpad.app.${appType}.settings.panel.workbench`} pressed={!!panelVisibility.leftSidePanel} onPressedChange={() => togglePanelVisibility("leftSidePanel")} text={showWorkbenchLabel} />
                <Toggle id={`compose.sketchpad.app.${appType}.settings.panel.windows`} pressed={!!panelVisibility.rightSidePanel} onPressedChange={() => togglePanelVisibility("rightSidePanel")} text={showWindowsLabel} />
                <Toggle id={`compose.sketchpad.app.${appType}.settings.panel.details`} pressed={!!panelVisibility.details} onPressedChange={() => togglePanelVisibility("details")} text={showDetailsLabel} />
              </>
            ),
          },
        ]}
      />
    </TreeStateProvider>
  );
};

const LayoutWrapper: FC = () => {
